export const PREGUNTAS: Pregunta[] = [
  { id:'t1-01', tema:1, n:1, q:'La señal alto, que realiza el agente de la autoridad en la vía la ejecuta:', opciones:['Con el brazo en posición vertical al frente','Con el brazo extendido horizontal al frente','Con uno o los dos brazos a continuación de los hombros'], correcta:2 },
  { id:'t1-02', tema:1, n:2, q:'En todos los casos estoy obligado a dar parte a la policía en caso de accidente', opciones:['Si en todos','Solo en los casos que resulten personas muertas o lesionados, que afecten la propiedad estatal o muebles e inmuebles','A veces'], correcta:1 },
  { id:'t1-03', tema:1, n:3, q:'Siempre que escuches el sonido de la sirena y luces a intervalos de un vehículo que requiere la prioridad en la circulación vial a que está obligado:', opciones:['Arrimar a la derecha y detener la marcha','Disminuir la velocidad','Detenerse en el lugar'], correcta:0 },
  { id:'t1-04', tema:1, n:4, q:'Cuando una persona que conduzca su vehículo en vías de doble sentido de dirección lo hará por el lado derecho del eje central de la vía en el sentido que circule', opciones:['Nunca','Siempre, excepto por fuerza mayor','Solo cuando circule un vehículo en sentido contrario'], correcta:1 },
  { id:'t1-05', tema:1, n:5, q:'Las líneas tipo cebra, indican:', opciones:['Una zona donde solo circulan peatones','Una isleta que los vehículos no deben parquear','El lugar destinado para que los peatones crucen la vía'], correcta:2 },
  { id:'t1-06', tema:1, n:6, q:'Usted, como conductor de cualquier vehículo de motor, al circular por una vía deberá tener presente:', opciones:['Circular por la izquierda, en una vía urbana o rural de doble sentido de dirección','No circular por la izquierda, en sentido contrario, en una vía de doble sentido de dirección en zona urbana o rural.','Circular por el carril del centro, en una vía de tres o más sendas destinadas a la circulación en un mismo sentido, cuando se circula a marcha lenta'], correcta:1 },
  { id:'t1-07', tema:1, n:7, q:'Usted, como conductor de cualquier vehículo de motor, al circular por una vía, está obligado a mantener el máximo de velocidad autorizado cuando:', opciones:['Circule por la senda o carril de la extrema izquierda, en todas las vías de dos o más sendas o carriles destinados a la circulación en un mismo sentido.','Circule por la senda o carril de la extrema derecha, solo cuando lo haga por una vía rural de dos o más sendas o carriles destinados a la circulación en un mismo sentido','Circule por una senda o carril central en una vía de tres sendas destinadas a la circulación en un mismo sentido'], correcta:2 },
  { id:'t1-08', tema:1, n:8, q:'Usted, como conductor de cualquier vehículo de motor, cuando circule por una vía está obligado a:', opciones:['Utilizar el carril o senda de la extrema derecha, en vías de dos sendas o carriles en un mismo sentido de dirección, solo en zona rural','Utilizar el carril o senda derecha, en vías urbanas de dos sendas o carriles en un mismo sentido de dirección, cuando las condiciones físicas de la vía lo permitan','Utilizar el carril o senda de la extrema derecha, cuando circule a marcha lenta en vías de tres o más sendas o carriles en un mismo sentido de dirección, tanto en zona urbana como en rural.'], correcta:2 },
  { id:'t1-09', tema:1, n:9, q:'Usted, como conductor de cualquier vehículo de motor, al circular por una vía tanto en zona urbana como en rural, deberá tener en cuenta:', opciones:['Utilizar el carril o senda de la extrema izquierda, en vías rurales de dos o más sendas o carriles en un mismo sentido de dirección, cuando transite a una velocidad inferior a 60 kilómetros por hora.','Utilizar las sendas extremas a ambos lados de la calzada, en vías de tres sendas o carriles con doble sentido de circulación, quedando el carril central para el adelantamiento de los vehículos en ambos sentidos de dirección.','Utilizar la senda del centro, en vías de tres sendas o carriles con doble sentido de circulación, siempre que las condiciones de visibilidad lo permitan'], correcta:1 },
  { id:'t1-10', tema:1, n:10, q:'¿Cuándo una persona que conduzca un vehículo en vías de doble sentido de dirección, lo hará por el lado derecho del eje central de la vía en el sentido en que circule?', opciones:['Solo cuando circule un vehículo en sentido contrario','Siempre, excepto por fuerza mayor.','Nunca'], correcta:1 },
  { id:'t1-11', tema:1, n:11, q:'Todo conductor que circule por una vía, al escuchar el sonido de la sirena o aparato similar u observe la luz intermitente, advirtiendo la proximidad de un vehículo requiriendo la prioridad en la circulación, está obligado a:', opciones:['Arrimarlo y detenerlo al borde derecho de la vía, en el sentido en que circula.','Cambiar de senda o carril utilizando el inmediato derecho, cuando transita por una vía de más de dos sendas','Continuar su desplazamiento por la senda o carril por el que se encuentre circulando'], correcta:0 },
  { id:'t1-12', tema:1, n:12, q:'El conductor de un vehículo implicado en un accidente del tránsito está obligado a:', opciones:['Dar cuenta de inmediato a la Policía Nacional Revolucionaria en todos los casos y ante cualquier circunstancia','Dar cuenta de inmediato a la Policía Nacional Revolucionaria solo en los casos en que resulten personas muertas o lesionadas','Dar cuenta de inmediato a la Policía Nacional Revolucionaria en todos los casos en que resulten personas muertas o lesionadas y en todos los que participe un vehículo estatal o se afecte la propiedad estatal.'], correcta:2 },
  { id:'t1-13', tema:1, n:13, q:'El conductor de un vehículo implicado en un accidente del tránsito está obligado a mantener el vehículo en la posición que resulte del accidente:', opciones:['Excepto cuando se haga necesario restablecer la circulación para evitar la congestión vehicular','Siempre que se haya originado la muerte o lesiones a alguna persona, excepto en los casos en que deba trasladar alguna víctima.','Cualesquiera que sean los resultados y consecuencias del hecho'], correcta:1 },
  { id:'t1-14', tema:1, n:14, q:'El conductor implicado en un accidente de tránsito, ¿Qué debe hacer en el lugar del hecho?', opciones:['Tomar las medidas para advertir del hecho a los demás usuarios de la vía.','Revisar el vehículo para ver que afectaciones tuvo','Localizar a los vecinos para reparar el vehículo'], correcta:0 },
  { id:'t1-15', tema:1, n:15, q:'¿Debe permanecer el conductor implicado en un accidente en el lugar del hecho?', opciones:['No, debe trasladarse de inmediato a la Unidad de la Policía','No, si el accidente es de noche','Sí, excepto para trasladar víctimas a recibir asistencia médica o tenga él que recibirla.'], correcta:2 },
  { id:'t1-16', tema:1, n:16, q:'Las señales que realiza el agente de la autoridad en la vía, levantando el brazo verticalmente significa:', opciones:['"Atención, Alto", y todos los usuarios de la vía deben detenerse de inmediato.','"Alto", y todos los usuarios de la vía que se encuentren de frente o de espalda del agente deben detenerse de inmediato','"Alto", y todos los usuarios de la vía que no se encuentren de frente o de espalda del agente, pueden continuar la marcha y realizar todas las maniobras que no están prohibidas en el cruce o en la intersección'], correcta:0 },
  { id:'t1-17', tema:1, n:17, q:'La señal que realiza el agente de la autoridad en la vía, con uno o los dos brazos extendidos horizontalmente como continuación de su hombro, significa:', opciones:['"Alto", y todos los usuarios de la vía que se encuentren de frente o de espalda del agente pueden continuar en ese sentido y realizar todas aquellas maniobras que no estén prohibidas en el cruce','"Alto", y todos los usuarios de la vía que se encuentren de frente o de espalda del agente deben detenerse de inmediato y solamente los que se encuentran en el mismo sentido de dirección del brazo o los brazos pueden continuar en ese mismo sentido o realizar todas las maniobras que no estén prohibidas.','"Atención, Alto", y todos los usuarios de la vía deben detenerse de inmediato'], correcta:1 },
  { id:'t1-18', tema:1, n:18, q:'La señal que realiza el agente de la autoridad con el brazo extendido horizontalmente al frente indica:', opciones:['A los conductores de los vehículos que se encuentren de frente o a espalda del agente, que pueden realizar la maniobra de giro a la izquierda','A los conductores de los vehículos que se encuentren a su izquierda, que pueden circular en todas direcciones y a los peatones que pueden cruzar a su espalda.','A los conductores de los vehículos que se encuentren a su derecha, que pueden circular en todas direcciones'], correcta:1 },
  { id:'t1-19', tema:1, n:19, q:'La señal que realiza el agente de la autoridad mediante el balanceo manual de una luz roja indica:', opciones:['A los usuarios de la vía hacia los cuales está dirigida la luz roja que deben detenerse.','A los usuarios de la vía hacia los cuales está dirigida la luz roja, que pueden circular en sentido recto o girar a la derecha','A los usuarios de la vía hacia los cuales está dirigida la luz roja, que pueden continuar con precaución'], correcta:0 },
  { id:'t1-20', tema:1, n:20, q:'La señal que realiza el agente de la autoridad, mediante una serie de toques cortos de silbato indica:', opciones:['Que los vehículos deben disminuir la velocidad por aproximarse a alguna interrupción en la vía','Que los vehículos deben detenerse.','Que los vehículos pueden continuar la marcha'], correcta:1 },
  { id:'t1-21', tema:1, n:21, q:'La señal que realiza el agente de la autoridad, mediante un toque largo de silbato indica:', opciones:['Que los vehículos pueden continuar la marcha.','La aproximación a una interrupción en la vía resultando necesario disminuir la velocidad','Que los vehículos deben detenerse'], correcta:0 },
  { id:'t1-22', tema:1, n:22, q:'Toda persona que conduzca un vehículo de motor por una vía, al realizar cualquier maniobra, está obligada a:', opciones:['Accionar las señales de luces de frenado y las direccionales e intermitentes, mecánicas o eléctricas del vehículo o, en su defecto, las de brazos correspondientes para avisar la maniobra que pretende realizar a los demás usuarios de la vía.','Accionar las luces direccionales e intermitentes y sacar el brazo en posición vertical hacia arriba, para doblar o cambiar de carril o senda a la izquierda','Accionar las luces de frenado y sacar el brazo y extenderlo en posición horizontal, con la palma de la mano hacia abajo, para disminuir la velocidad o parar'], correcta:0 },
  { id:'t1-23', tema:1, n:23, q:'Para advertir al conductor del vehículo que circula detrás del suyo, su intención de realizar un cambio de dirección a la derecha (un giro o cambio de senda) deberá indicarlo haciendo una señal con su brazo:', opciones:['Manteniéndolo inclinado hacia abajo, con la palma de la mano hacia atrás','En posición vertical hacia arriba.','Extendido en posición horizontal, con la palma de la mano hacia abajo'], correcta:1 },
  { id:'t1-24', tema:1, n:24, q:'Circulando por una vía de doble sentido de dirección, usted pretende incorporarse a la transversal, realizando un giro a la izquierda, indica la maniobra a los demás usuarios de la vía, colocando el brazo:', opciones:['En posición inclinada hacia abajo, con la palma de la mano hacia atrás','Extendido en posición horizontal.','En posición vertical hacia arriba'], correcta:1 },
  { id:'t1-25', tema:1, n:25, q:'Durante la conducción de un vehículo de motor por una vía, antes de realizar cualquier maniobra de giro o cambio de carril o senda, está usted obligado a accionar las señales de luces direccionales e intermitentes o las de brazo correspondiente y:', opciones:['Efectuar el giro o el cambio de senda o carril inmediatamente','Cerciorarse antes de efectuar la maniobra que no ocasionará interferencia a la circulación, ni dará lugar a un accidente.','Realizar la maniobra por el paseo'], correcta:1 },
  { id:'t1-26', tema:1, n:26, q:'¿Dónde se prohíbe adelantar a otro vehículo?', opciones:['En cambios de rasante en vías de dos o más sendas en el mismo sentido','En curvas de visibilidad reducida.','En vías de doble sentido de circulación a 100 metros de un paso a nivel'], correcta:1 },
  { id:'t1-27', tema:1, n:27, q:'¿Dónde se prohíbe adelantar a otro vehículo?', opciones:['A 150 metros de una curva','A 100 metros de un túnel','En un cambio de rasante.'], correcta:2 },
  { id:'t1-28', tema:1, n:28, q:'¿Dónde se prohíbe realizar la maniobra de adelantamiento cuando se aproxima a un paso a nivel?', opciones:['Solo en vías de dos o más carriles de circulación en un mismo sentido','En cualquier tipo de vía.','Solo en vías de doble sentido de circulación, con un o dos carriles'], correcta:1 },
  { id:'t1-29', tema:1, n:29, q:'En las señales horizontales ¿Qué es lo que indica la regulación?', opciones:['El color de la pintura de la marca','El diseño de su trazado en el pavimento.','El lugar donde está ubicada'], correcta:1 },
  { id:'t1-30', tema:1, n:30, q:'Esta marca significa...:', opciones:['Que ningún vehículo podrá cruzarla o circular sobre ella.','Que se está próximo a una intersección','Que puede cruzarse cuando el volumen vehicular así lo requiera'], correcta:0, marca:'m-linea-continua' },
  { id:'t1-31', tema:1, n:31, q:'Usted, como conductor de cualquier vehículo de motor, al circular por la vía, debe tener en cuenta que esta marca indica:', opciones:['Que ningún vehículo podrá cruzarla o circular sobre ella','Que los vehículos pueden cruzarla según lo requieran.','Que se acerca una intersección'], correcta:0 },
  { id:'t1-32', tema:1, n:32, q:'Estas dos líneas paralelas continuas significan...:', opciones:['Que ningún vehículo podrá cruzarlas o circular sobre ellas, solo de noche','Que los conductores solo podrán cruzarlas cuando requieran hacer una maniobra de adelantamiento','Que ningún vehículo podrá cruzarlas ni circular sobre ellas.'], correcta:2, marca:'m-doble-continua' },
  { id:'t1-33', tema:1, n:33, q:'Que significa dos líneas paralelas en el centro de la vía continua y discontinua:', opciones:['Que los conductores no pueden cruzarlas cuando a su izquierda se encuentra primero la línea continua.','Que los conductores no pueden cruzarlas cuando a su izquierda se encuentra primero la línea discontinua','Que los conductores no pueden cruzarlas independientemente de la posición que se encuentren estas marcas'], correcta:1, marca:'m-continua-discontinua' },
  { id:'t1-34', tema:1, n:34, q:'La línea continua del borde de la calzada significa...:', opciones:['Que ningún vehículo podrá cruzarlas ni circular sobre ella','Que puede cruzarse para efectuar una detención, sin que el vehículo quede en una posición tal que afecte o perjudique la circulación de los demás usuarios.','Tienen por objetivo impedir el paso de los vehículos y a la vez orientarlos en el o los sentidos de circulación permisibles'], correcta:1, marca:'m-linea-borde' },
  { id:'t1-35', tema:1, n:35, q:'La línea continua de canalización significa...:', opciones:['Indican el sentido y la dirección correcta que deben tomar los conductores de vehículos','Indica que la vía es de doble sentido','Delimitan los carriles en áreas críticas de la circulación.'], correcta:2, marca:'m-canalizacion' },
  { id:'t1-36', tema:1, n:36, q:'La línea de "Pare" significa...:', opciones:['Detenerse ante ella.','Detenerse sobre ella','Detenerse después de ella'], correcta:0 },
  { id:'t1-37', tema:1, n:37, q:'La línea de "Ceda el Paso" significa...:', opciones:['Detenerse antes de ella siempre','Detenerse ante ella cuando se tiene que ceder el paso.','Detenerse después de ella siempre'], correcta:1 },
  { id:'t1-38', tema:1, n:38, q:'El paso tipo "cebra" indica...:', opciones:['Una zona donde sólo circulan peatones','Una isleta que los vehículos no deben franquear','El lugar destinado para que los peatones crucen la vía.'], correcta:2 },
  { id:'t1-39', tema:1, n:39, q:'La doble línea para el cruce de peatones indica...:', opciones:['Que el conductor está obligado a detenerse ante ellas','Un lugar para que los peatones crucen la vía.','Que los conductores no deben moderar la velocidad en ningún caso'], correcta:1 },
  { id:'t1-40', tema:1, n:40, q:'Si existen dos líneas de "PARE" marcadas sobre el pavimento ¿Cuál es para la detención de los ciclos?', opciones:['La más alejada de la intersección','La más cercana a la intersección.','Las dos'], correcta:1 },
  { id:'t1-41', tema:1, n:41, q:'Si existe sobre el pavimento la inscripción de "PARE" ¿Qué es lo que indica?', opciones:['Detenerse antes de ella','Detenerse después de ella en la línea de "PARE" o señal de "PARE".','Que está próxima una intersección con prioridad'], correcta:1 },
  { id:'t1-42', tema:1, n:42, q:'Los usuarios de las vías están obligados a observar en el cumplimiento de las reglas del tránsito el orden de prioridad siguiente:', opciones:['Señales de los agentes de la autoridad; 2-señales mediante luces de los semáforos; 3-señales verticales y; 4-señales horizontales.','Señales mediante luces de los semáforos; 2-señales de los agentes de la autoridad; 3-señales verticales y; 4-señales horizontales','Señales de los agentes de la autoridad; 2-señales mediante luces de los semáforos; 3-señales horizontales y; 4-señales verticales'], correcta:0 },
  { id:'t2-01', tema:2, n:1, q:'Que debe hacer un conductor ante la luz amarilla intermitente de un semáforo:', opciones:['Detenerse en la línea de pare','Cruzar con extrema precaución','Aumentar la velocidad'], correcta:1 },
  { id:'t2-02', tema:2, n:2, q:'Cual es la velocidad mínima obligatoria en los túneles:', opciones:['60km/h','70km/h','La que indica la señal'], correcta:0 },
  { id:'t2-03', tema:2, n:3, q:'Cual es la velocidad establecida en la zona urbana para los vehículos con arrastres:', opciones:['30 km/h','60 km/h','50 km/h'], correcta:0 },
  { id:'t2-04', tema:2, n:4, q:'Cuáles son los vehículos que para circular por las vías principales necesitan permiso del MINIT:', opciones:['Vehículos que trasportan animales','Vehículos que trasporten personas','Tractores y vehículos especializados en la construcción'], correcta:2 },
  { id:'t2-05', tema:2, n:5, q:'¿Cuándo se puede realizar una maniobra de marcha atrás?', opciones:['Velocidad inferior a los 20 kilómetros por hora.','Distancia a recorrer de 30 metros','En un túnel'], correcta:1 },
  { id:'t2-06', tema:2, n:6, q:'Al conducir un vehículo por una vía rural de dos carriles al mismo sentido de circulación, usted como conductor deberá tener presente:', opciones:['Hacerlo por el carril inmediato izquierdo cuando transite a velocidad inferior de 60 km/h','Hacerlo siempre por el carril de la extrema derecha, cuando transite a una velocidad inferior a los 60 km/h','Hacerlo siempre por el carril de su extrema derecha cuando transite a la máxima velocidad permitida'], correcta:0 },
  { id:'t2-07', tema:2, n:7, q:'Si en una intersección semaforizada de bajo volumen de transito o en determinadas horas del día hay una o dos luces rojas intermitentes alternativamente, que debe hacer usted', opciones:['Moderar la velocidad y pasar con precaución','Continuar normal ya que tiene derecho de vía','Detenerse y continuar cuando la vía transversal no se aproxime ningún vehículo'], correcta:2 },
  { id:'t2-08', tema:2, n:8, q:'Circulando usted por una autopista, conduciendo su vehículo que lleva remolque, la velocidad para su desplazamiento no puede exceder:', opciones:['90 km/h','70 km/h','80 km/h'], correcta:2 },
  { id:'t2-09', tema:2, n:9, q:'Cuando usted circule por una carretera, conduciendo un vehículo rígido, la velocidad para el desplazamiento no deberá exceder:', opciones:['90 km/h','70 km/h','80 km/h'], correcta:0 },
  { id:'t2-10', tema:2, n:10, q:'¿Cuándo el conductor de cualquier vehículo puede realizar la maniobra de marcha atrás?', opciones:['La distancia a recorrer no exceda 20 metros, debiendo observar la vía detrás del vehículo mientras dure la maniobra.','La velocidad sea de 30 kilómetros por hora','Obstrucción la circulación levemente'], correcta:0 },
  { id:'t2-11', tema:2, n:11, q:'¿Cuándo el conductor de cualquier vehículo puede realizar la maniobra de marcha atrás?', opciones:['A una distancia 30 metros','Obligue a otro vehículo a realizar un cambio en su dirección o velocidad','La velocidad no exceda los 20 kilómetros por hora.'], correcta:2 },
  { id:'t2-12', tema:2, n:12, q:'Cuándo el conductor de cualquier vehículo puede realizar la maniobra de marcha atrás?', opciones:['No obligue a otro vehículo que se aproxime a realizar un cambio brusco en su dirección o velocidad.','La velocidad es de 30 kilómetros por hora','La distancia a recorrer es de 25 metros'], correcta:0 },
  { id:'t2-13', tema:2, n:13, q:'¿Cuándo puede un tractor circular por las vías de interés nacional, provincial o municipal?', opciones:['Siempre, ya que está permitido totalmente','Nunca, ya que está prohibido','Con el permiso del Ministerio del Interior.'], correcta:2 },
  { id:'t2-14', tema:2, n:14, q:'¿Qué tipo de vehículo tiene prohibida la circulación por los túneles?', opciones:['Vehículos que transportan materias tóxicas, inflamables o explosivas.','Vehículos que en su circulación no sean capaces de alcanzar una velocidad mínima de 70 kilómetros por hora','Vehículos cuyo peso máximo autorizado no exceda de 3 500 kilogramos'], correcta:0 },
  { id:'t2-15', tema:2, n:15, q:'¿Qué tipo de vehículo tiene prohibida la circulación por los túneles?', opciones:['Vehículos articulados','Vehículos cuyo peso máximo autorizado exceda de los 6 000 kilogramos','Vehículos que en su circulación no son capaces de alcanzar y mantener una velocidad de 60 kilómetros por hora.'], correcta:2 },
  { id:'t2-16', tema:2, n:16, q:'Usted, como conductor de cualquier vehículo de motor debe tener presente que, como límite máximo de velocidad, en vías urbanas se establece:', opciones:['50 kilómetros por hora para todos los vehículos.','60 kilómetros por hora para los automóviles de hasta 3 500 kilogramos y los ómnibus','40 kilómetros por hora para los automóviles dedicados al transporte de carga'], correcta:0 },
  { id:'t2-17', tema:2, n:17, q:'Circulando usted por una carretera, conduciendo una moto, la velocidad para su desplazamiento no puede exceder:', opciones:['70 kilómetros por hora','90 kilómetros por hora.','80 kilómetros por hora'], correcta:1 },
  { id:'t2-18', tema:2, n:18, q:'Transitando usted por una carretera, conduciendo un vehículo rígido o articulado, destinado al transporte de carga, la velocidad que podrá desarrollar en su desplazamiento no excederá de:', opciones:['80 kilómetros por hora.','90 kilómetros por hora','100 kilómetros por hora'], correcta:0 },
  { id:'t2-19', tema:2, n:19, q:'Transitando usted por una carretera, conduciendo una grúa la velocidad que podrá desarrollar en su trayectoria no excederá:', opciones:['60 kilómetros por hora','70 kilómetros por hora.','80 kilómetros por hora'], correcta:1 },
  { id:'t2-20', tema:2, n:20, q:'Que significa dos líneas paralelas en el centro de la vía continua y discontinua:', opciones:['Que los conductores no pueden cruzarlas cuando a su izquierda se encuentra primero la línea continua.','Que los conductores no pueden cruzarlas cuando a su izquierda se encuentra primero la línea discontinua','Que los conductores no pueden cruzarlas independientemente de la posición que se encuentren estas marcas'], correcta:0 },
  { id:'t2-21', tema:2, n:21, q:'Conduciendo usted por una autopista, un automóvil que no excede en su peso los 3 500 kilogramos, la velocidad que puede alcanzar con su vehículo no será superior a:', opciones:['100 kilómetros por hora.','90 kilómetros por hora','80 kilómetros por hora'], correcta:0 },
  { id:'t2-22', tema:2, n:22, q:'Conduciendo usted por una autopista, un vehículo que no excede en su peso los 3 500 kilogramos, la velocidad que puede alcanzar no será superior a:', opciones:['90 kilómetros por hora','70 kilómetros por hora','100 kilómetros por hora.'], correcta:2 },
  { id:'t2-23', tema:2, n:23, q:'Transitando usted por una autopista, conduciendo un vehículo rígido o articulado, destinado al transporte de carga, la velocidad que podrá desarrollar en su trayectoria no excederá:', opciones:['80 kilómetros por hora','70 kilómetros por hora','90 kilómetros por hora.'], correcta:2 },
  { id:'t2-24', tema:2, n:24, q:'Circulando usted por una autopista conduciendo una grúa la velocidad para su desplazamiento no puede exceder:', opciones:['80 kilómetros por hora.','70 kilómetros por hora','60 kilómetros por hora'], correcta:0 },
  { id:'t2-25', tema:2, n:25, q:'Circulando usted por una autopista, conduciendo un vehículo que lleva remolque o arrastra a otro vehículo, la velocidad para su desplazamiento no puede exceder:', opciones:['90 kilómetros por hora','70 kilómetros por hora','80 kilómetros por hora.'], correcta:2 },
  { id:'t2-26', tema:2, n:26, q:'Circula usted con un equipo especializado para la construcción, tractores u otros equipos agrícolas, la velocidad que puede alcanzar con su vehículo no será superior a:', opciones:['60 kilómetros por hora','20 kilómetros por hora.','50 kilómetros por hora'], correcta:1 },
  { id:'t2-27', tema:2, n:27, q:'Usted, como conductor de cualquier vehículo de motor debe tener en cuenta que:', opciones:['Por camino de tierra o terraplén, la velocidad máxima autorizada es de 50 kilómetros por hora','En los túneles, la velocidad se mantendrá a 50 kilómetros por hora','No se conducirá un automóvil a tan baja velocidad que afecte la fluidez de la circulación.'], correcta:2 },
  { id:'t2-28', tema:2, n:28, q:'El conductor de cualquier vehículo de motor debe tener en cuenta que:', opciones:['En camino de tierra o terraplén, no se conducirá a una velocidad superior a los 60 kilómetros por hora.','En zona urbana la velocidad máxima es de 60 kilómetros por hora','En los túneles, la velocidad se mantendrá a 70 kilómetros por hora'], correcta:0 },
  { id:'t2-29', tema:2, n:29, q:'El conductor de cualquier vehículo de motor debe tener en cuenta que:', opciones:['En las salidas de garajes, edificios, vías o parqueos interiores, la velocidad máxima autorizada es 30 kilómetros por hora, en zona urbana','En los túneles, la velocidad se mantendrá a 60 kilómetros por hora.','En los intercambios no se modera la velocidad'], correcta:1 },
  { id:'t2-30', tema:2, n:30, q:'El conductor de cualquier vehículo de motor debe tener en cuenta que:', opciones:['En los túneles se mantendrá a 40 kilómetros por hora','No se excederán los 40 kilómetros por hora de velocidad al circular por un camino de tierra o terraplén','En las salidas de garajes, edificios, vías o parqueos interiores, la velocidad no excederá de 20 kilómetros por hora.'], correcta:2 },
  { id:'t2-31', tema:2, n:31, q:'Usted, como conductor de cualquier vehículo de motor debe tener en cuenta que:', opciones:['En zonas de niños, la velocidad no excederá de 40 kilómetros por hora en zona urbana.','Los autos circularan como máximo a 70 kilómetros por hora en las carreteras','No se excederán los 40 kilómetros por hora de velocidad al circular por un camino de tierra o terraplén'], correcta:0 },
  { id:'t2-32', tema:2, n:32, q:'Usted, como conductor de cualquier vehículo de motor debe tener en cuenta que:', opciones:['En los túneles, la velocidad mínima obligatoria no excederá los 50 kilómetros por hora','En las salidas de garajes, edificios, vías o parqueos interiores, la velocidad máxima es de 30 kilómetros por hora, en zona rural','En zonas de niños, la velocidad no excederá de 60 kilómetros por hora en zona rural, los días y horas laborables.'], correcta:2 },
  { id:'t2-33', tema:2, n:33, q:'Usted, como conductor de cualquier vehículo debe tener en cuenta que la luz roja del semáforo indica que:', opciones:['Detenerse.','Moderar velocidad y parar si es necesario','Ceder el paso'], correcta:0 },
  { id:'t2-34', tema:2, n:34, q:'Si existen una o dos luces rojas intermitentes alternativamente -¿Qué debe hacerse?', opciones:['Detenerse solo conductores de vehículos.','Detenerse solo los peatones','Detenerse conductores de vehículos y peatones'], correcta:0 },
  { id:'t2-35', tema:2, n:35, q:'Si en una intersección semaforizada de bajo volumen de tránsito o en determinadas horas de día hay una o dos luces rojas intermitentes alternativamente -¿Qué debe hacer?', opciones:['Moderar la velocidad y pasar con precaución','Continuar normal ya que se tiene derecho de vía','Detenerse, y continuar cuando por la vía transversal no se aproxima ningún vehículo.'], correcta:2 },
  { id:'t2-36', tema:2, n:36, q:'Usted, como conductor de cualquier vehículo de motor debe tener en cuenta que:', opciones:['En zonas de niños, la velocidad no excederá de 40 kilómetros por hora en zona urbana.','Los autos circularan como máximo a 70 kilómetros por hora en las carreteras','No se excederán los 40 kilómetros por hora de velocidad al circular por un camino de tierra o terraplén'], correcta:0 },
  { id:'t2-37', tema:2, n:37, q:'¿Qué hacen los conductores ante la luz amarilla intermitente del semáforo?', opciones:['Continuar la marcha con precaución.','Detenerse en la línea de "Pare"','Disminuir la velocidad y parar si es necesario'], correcta:0 },
  { id:'t2-38', tema:2, n:38, q:'La luz vede intermitente alerta a los usuarios de la vía que...:', opciones:['Su tiempo acaba de comenzar','Su tiempo está por concluir.','Ambas cosas'], correcta:1 },
  { id:'t2-39', tema:2, n:39, q:'¿Que hacen los conductores ante la luz verde del semáforo en vías de una sola dirección?', opciones:['Realizar el giro en forma de "U"','Continuar la marcha por la vía en que circula, doblar a la derecha o a la izquierda.','Ceder el paso'], correcta:1 },
  { id:'t2-40', tema:2, n:40, q:'Si en una intersección hay una sección adicional al semáforo normal, de color verde con flecha a la izquierda, y ésta se enciende al mismo tiempo que la luz roja de la sección normal -¿Qué debe hacer si usted está en el carril de girar a la izquierda?', opciones:['Girar a la izquierda.','Detenerse','Seguir recto'], correcta:0 },
  { id:'t2-41', tema:2, n:41, q:'En una intersección semaforizada de una vía de doble sentido de dirección -¿Cuándo puede realizarse un giro en forma de "U"?', opciones:['Cuando se enciende la luz verde que permite el giro izquierda y existe la señal que lo autoriza.','Cuando no viene nadie en el sentido contrario, sin importar las luces del semáforo','Cuando existe la señal que lo autoriza, con cualquier luz'], correcta:0 },
  { id:'t2-42', tema:2, n:42, q:'Usted, como conductor de cualquier vehículo de motor debe tener en cuenta que:', opciones:['Por camino de tierra o terraplén, la velocidad máxima autorizada es de 50 kilómetros por hora','En los túneles, la velocidad se mantendrá a 50 kilómetros por hora','No se conducirá un automóvil a tan baja velocidad que afecte la fluidez de la circulación.'], correcta:2 },
  { id:'t2-43', tema:2, n:43, q:'El conductor de cualquier vehículo de motor debe tener en cuenta que:', opciones:['En camino de tierra o terraplén, no se conducirá a una velocidad superior a los 60 kilómetros por hora.','En zona urbana la velocidad máxima es de 60 kilómetros por hora','En los túneles, la velocidad se mantendrá a 70 kilómetros por hora'], correcta:0 },
  { id:'t2-44', tema:2, n:44, q:'El conductor de cualquier vehículo de motor debe tener en cuenta que:', opciones:['En las salidas de garajes, edificios, vías o parqueos interiores, la velocidad máxima autorizada es 30 kilómetros por hora, en zona urbana','En los túneles, la velocidad se mantendrá a 60 kilómetros por hora.','En los intercambios no se modera la velocidad'], correcta:1 },
  { id:'t2-45', tema:2, n:45, q:'El conductor de cualquier vehículo de motor debe tener en cuenta que:', opciones:['En los túneles se mantendrá a 40 kilómetros por hora','No se excederán los 40 kilómetros por hora de velocidad al circular por un camino de tierra o terraplén','En las salidas de garajes, edificios, vías o parqueos interiores, la velocidad no excederá de 20 kilómetros por hora.'], correcta:2 },
  { id:'t2-46', tema:2, n:46, q:'Usted, como conductor de cualquier vehículo de motor debe tener en cuenta que:', opciones:['En zonas de niños, la velocidad no excederá de 40 kilómetros por hora en zona urbana, los días y horas laborables.','Los autos circularan como máximo a 70 kilómetros por hora en las carreteras','No se excederán los 40 kilómetros por hora de velocidad al circular por un camino de tierra o terraplén'], correcta:0 },
  { id:'t2-47', tema:2, n:47, q:'Usted, como conductor de cualquier vehículo de motor debe tener en cuenta que:', opciones:['En los túneles, la velocidad mínima obligatoria no excederá los 50 kilómetros por hora','En las salidas de garajes, edificios, vías o parqueos interiores, la velocidad máxima es de 30 kilómetros por hora, en zona rural','En zonas de niños, la velocidad no excederá de 60 kilómetros por hora en zona rural, los días y horas laborables.'], correcta:2 },
  { id:'t2-48', tema:2, n:48, q:'Al conducir un vehículo por una vía rural de más de dos carriles destinados al mismo sentido de circulación, usted como conductor deberá tener presente:', opciones:['Hacerlo por el carril inmediato izquierdo, cuando transite a velocidad inferior a los 60 kilómetros por hora','Hacerlo siempre por el carril de su extrema derecha, cuando transite a una velocidad inferior a los 60 kilómetros por hora, y utilizar el inmediato izquierdo para adelantar.','Hacerlo siempre por el carril de su extrema derecha cuando transite a la máxima velocidad permitida'], correcta:1 },
  { id:'t3-01', tema:3, n:1, q:'Cuál es la longitud de un vehículo articulado:', opciones:['La establecida por el jefe central','10 metros','18 metros'], correcta:2 },
  { id:'t3-02', tema:3, n:2, q:'Esta permitido a los conductores dedicados al transporte de carga circular transportando pasajeros', opciones:['Si, siempre, ya que esta permitido totalmente','Si, a veces cuando se cumple lo dispuesto en los artículos 135 y 136 de la Ley 109','No, nunca, ya que esta prohibido'], correcta:1 },
  { id:'t3-03', tema:3, n:3, q:'La longitud máxima de un vehículo rígido es de....', opciones:['15 metros.','10 metros.','18 metros'], correcta:0 },
  { id:'t3-04', tema:3, n:4, q:'La longitud máxima de un vehículo articulado es de....', opciones:['12 metros.','18 metros.','10 metros.'], correcta:1 },
  { id:'t3-05', tema:3, n:5, q:'La longitud máxima de un conjunto de vehículos es de....', opciones:['Cualquiera.','12 metros.','18 metros.'], correcta:2 },
  { id:'t3-06', tema:3, n:6, q:'La anchura máxima de un vehículo es de....', opciones:['2,50 metros.','2,60 metros.','2,00 metros'], correcta:1 },
  { id:'t3-07', tema:3, n:7, q:'La altura máxima de un vehículo no debe exceder de....', opciones:['4 metros.','3,50 metros','5 metros'], correcta:0 },
  { id:'t3-08', tema:3, n:8, q:'El peso máximo de la carga que transporte un vehículo no debe sobrepasar....', opciones:['El máximo autorizado por el dueño','El máximo autorizado por la empresa','El máximo autorizado por las condiciones técnicas del vehículo.'], correcta:2 },
  { id:'t3-09', tema:3, n:9, q:'La carga útil máxima de un vehículo rígido o articulado no debe sobrepasar de....', opciones:['10 toneladas métricas.','30 toneladas métricas','20 toneladas métricas'], correcta:0 },
  { id:'t3-10', tema:3, n:10, q:'¿Cuándo un vehículo puede trasportar un número de personas que exceda el total permisible para garantizar la seguridad de los transportados?', opciones:['A veces, para una movilización','Nunca.','Siempre'], correcta:1 },
  { id:'t3-11', tema:3, n:11, q:'¿Cuándo puede circular un vehículo con las puertas abiertas?', opciones:['Nunca.','A veces','Siempre'], correcta:0 },
  { id:'t3-12', tema:3, n:12, q:'¿Está permitido interrumpir el tránsito de una vía en cualquier forma y por cualquier tiempo?', opciones:['Sí, siempre, ya que está permitido totalmente','No, nunca, ya que está prohibido','Sí, a veces, con el permiso del Ministerio del Interior.'], correcta:2 },
  { id:'t3-13', tema:3, n:13, q:'¿Cuándo se permite el trasbordo de mercancía o cualquier objeto de un vehículo a otro en la vía?', opciones:['En caso de accidente, rotura o desperfecto técnico.','Cuando se obstruye la circulación solo por media hora','Cuando obstruya la circulación'], correcta:0 },
  { id:'t3-14', tema:3, n:14, q:'Si antes de cruzar una intersección o paso de peatones, el conductor observa que la circulación esta obstruida más allá de dicha intersección o zona de peatones -¿Está permitido que las cruce?', opciones:['Sí, siempre, ya que está permitido totalmente','No, nunca, ya que está prohibido.','Sí, cuando no existan peatones o vehículos en la vía transversal'], correcta:1 },
  { id:'t3-15', tema:3, n:15, q:'¿Está prohibida la circulación en zonas urbanizadas a los vehículos de trasporte de carga de más de 10000 kilogramos?', opciones:['No, nunca','Sí, siempre','Sí, salvo con la autorización del Ministerio del Interior.'], correcta:2 },
  { id:'t3-16', tema:3, n:16, q:'¿Está permitido a los conductores de vehículos dedicados al transporte de carga, circular transportando pasajeros?', opciones:['Sí, siempre, ya que está permitido totalmente','No, nunca, ya que está prohibido','Sí, a veces, cuando se cumple lo dispuesto en los artículos 135 y 136 de la Ley 109.'], correcta:2 },
  { id:'t3-17', tema:3, n:17, q:'¿Cuándo se permite la reparación de cualquier vehículo en la vía?', opciones:['Nunca','A veces, en casos de fuerza mayor y por el tiempo mínimo indispensable.','Siempre'], correcta:1 },
  { id:'t3-18', tema:3, n:18, q:'¿Está prohibido remolcar a otro con una cuerda o cable no mayor de 8 metros?', opciones:['Siempre','A veces, excepto cuando el sistema de frenos del remolcado está defectuoso.','Nunca'], correcta:1 },
  { id:'t3-19', tema:3, n:19, q:'¿Cuándo un vehículo remolcado debe estar provisto de bandera roja, u otro medio similar, en la parte trasera o en otro lugar perceptible?', opciones:['Siempre.','Nunca','A veces'], correcta:0 },
  { id:'t3-20', tema:3, n:20, q:'Todo conductor de un vehículo de carga dedicado al transporte de personas deberá tener presente que:', opciones:['Podrá transportar personas sentadas en las barandas del vehículo cuando este no cuente con bancos o asientos','Solo transportará cinco personas de pie por cada metro cuadrado','La velocidad máxima no excederá los 40 kilómetros por hora en zona urbana y los 60 kilómetros por hora en zona rural.'], correcta:2 },
  { id:'t3-21', tema:3, n:21, q:'Todo conductor de un vehículo de carga dedicado al transporte de personas deberá tener presente que:', opciones:['El vehículo debe estar provisto de barandas posteriores y laterales, resistentes a cualquier impacto de los pasajeros.','Las barandas del vehículo tendrán una altura mínima de 100 centímetros','Podrán transportar mayor número de personas de las que admita su capacidad, cuando las circunstancias así lo requieran'], correcta:0 },
  { id:'t3-22', tema:3, n:22, q:'Todo conductor de un vehículo de carga dedicado al transporte de personas deberá tener presente que:', opciones:['El vehículo debe estar provisto de barandas laterales y posteriores y, en su defecto, de cuerdas, cables o sogas resistentes, que permitan la sujeción y seguridad de los pasajeros','Las barandas del vehículo tengan una altura superior a los 120 centímetros.','Deberá llevar cerrada la tapa o baranda posterior, durante el viaje, excepto cuando las necesidades de la transportación requieran mantenerla abierta'], correcta:1 },
  { id:'t3-23', tema:3, n:23, q:'Todo conductor de un vehículo de carga dedicado al transporte de personas deberá tener presente:', opciones:['Que la velocidad máxima no excederá los 50 kilómetros por hora en zona urbana ni los 70 en zona rural','Transportar como máximo, a razón de cinco personas de pie por cada metro cuadrado, en viajes de una a dos horas de duración','Evitar bandazos, frenazos rápidos y otras maniobras similares.'], correcta:2 },
  { id:'t3-24', tema:3, n:24, q:'Todo conductor de un vehículo de carga dedicado al transporte de personas deberá tener presente que:', opciones:['Debe transportar el número de personas que corresponda, como máximo a razón de cuatro personas de pie por cada metro cuadrado, en viajes de una hora o menos de duración.','Solo podrá transportar personas sentadas en las barandas laterales o posteriores del vehículo, cuando no cuente con bancos o asientos, en viajes de una hora o más','No llevará cajas ni otro tipo de carga peligrosa, excepto cuando las necesidades de la transportación así lo requieran'], correcta:0 },
  { id:'t3-25', tema:3, n:25, q:'¿Está permitido que los vehículos circulen normalmente por las aceras, paseos y el separador central?', opciones:['Sí, siempre, ya que está permitido totalmente','No, nunca, ya que está prohibido.','Sí, a veces, cuando va con fallos técnicos'], correcta:1 },
  { id:'t3-26', tema:3, n:26, q:'Todo conductor de un vehículo de carga dedicado al transporte de personas deberá tener presente que:', opciones:['El vehículo estará provisto de barandas, y en su defecto, de cuerdas, cables o sogas resistentes al impacto de los pasajeros, en caso de frenazos rápidos','No transportará, sentadas en bancos o asientos, mayor número de personas de las que admite la capacidad del vehículo.','Llevar cerrada la tapa o baranda posterior durante el viaje, salvo que las necesidades de la transportación requieran lo contrario'], correcta:1 },
  { id:'t3-27', tema:3, n:27, q:'Todo conductor de un vehículo de carga dedicado al transporte de personas deberá tener presente que:', opciones:['Las barandas del vehículo tendrán una altura inferior a 120 centímetros','Llevará cajas u otro tipo de carga peligrosa solo en los casos que las necesidades de la transportación así lo requieran','No podrá transportar personas sentadas en las barandas laterales o posteriores del vehículo.'], correcta:2 },
  { id:'t3-28', tema:3, n:28, q:'Todo conductor de un vehículo de carga dedicado al transporte de personas deberá tener presente que:', opciones:['Llevará cerrada la tapa o baranda posterior durante el viaje.','Transportará mayor número de personas de las que admite su capacidad, cuando las personas viajen sentadas en bancos o asientos','Podrá transportar personas sentadas en la parte exterior del borde de la cama o caja, en viajes de una hora, cuando no posea bancos o asientos'], correcta:0 },
  { id:'t3-29', tema:3, n:29, q:'Todo conductor de un vehículo de carga dedicado al transporte de personas deberá tener presente que:', opciones:['Solo podrá transportar mayor números de personas de las que admite su capacidad, cuando las personas viajen sentadas en bancos o asientos','No podrá llevar cajas ni otro tipo de carga.','Podrá transportar personas sentadas en la parte exterior de la cama o caja, solo en viajes de una hora o más'], correcta:1 },
  { id:'t3-30', tema:3, n:30, q:'¿Podrá un vehículo de motor para el transporte de carga circular sin la hoja de ruta?', opciones:['No, nunca.','Sí, a veces','Sí, siempre'], correcta:0 },
  { id:'t3-31', tema:3, n:31, q:'¿Podrá un vehículo de motor para el transporte de carga realizar el recorrido por una vía no establecida en la hoja de ruta?', opciones:['Sí, a veces','No, nunca.','Sí, siempre'], correcta:1 },
  { id:'t3-32', tema:3, n:32, q:'La carga de un vehículo debe estar acondicionada y sujeta de modo que...', opciones:['No se moje','No reciba mucho sol','No ponga en peligro la integridad física de las personas, ni pueda causar daño a las cosas.'], correcta:2 },
  { id:'t3-33', tema:3, n:33, q:'La carga de un vehículo debe estar acondicionada y sujeta de modo que...', opciones:['No se arrastre por la vía, ni caiga sobre esta.','No provoque ningún ruido','No se vea'], correcta:0 },
  { id:'t3-34', tema:3, n:34, q:'La carga de un vehículo debe estar acondicionada y sujeta de modo que...', opciones:['No haga ruidos','No estorbe la visibilidad del conductor.','No se moje'], correcta:1 },
  { id:'t3-35', tema:3, n:35, q:'La carga de un vehículo debe estar acondicionada y sujeta de modo que...', opciones:['No provoque ruidos innecesarios, polvo u otras incomodidades.','No reciba mucho sol','Se mantenga seca'], correcta:0 },
  { id:'t3-36', tema:3, n:36, q:'La carga de un vehículo debe estar acondicionada y sujeta de modo que...', opciones:['No provoque ningún ruido','No tape u oculte las luces de frenado y los indicadores de dirección, los dispositivos reflectantes y el número de la placa o chapa.','Se mantenga seca'], correcta:1 },
  { id:'t3-37', tema:3, n:37, q:'¿Está autorizado a circular un vehículo cargado cuando la altura de la carga exceda de 4 metros sobre el pavimento?', opciones:['Sí, siempre','No.','Sí, a veces, con autorización de su empresa'], correcta:1 },
  { id:'t3-38', tema:3, n:38, q:'¿Está autorizado a circular un vehículo cargado cuando la carga sobresalga del ancho de su cama o caja?', opciones:['Sí, a veces, con permiso de su empresa','Sí, siempre','No.'], correcta:2 },
  { id:'t3-39', tema:3, n:39, q:'¿Está autorizado a circular un vehículo cargado cuando la carga sobresalga más de 2 metros de su cama o caja, por su extremo delantero o trasero?', opciones:['No.','Sí','A veces, autorizado por su empresa'], correcta:0 },
  { id:'t3-40', tema:3, n:40, q:'¿Está autorizado a circular un vehículo cargado cuando transporte materiales o residuos de cualquier clase, susceptible de esparcirse o caer en la vía?', opciones:['Sí, siempre','Cuando estén cubiertos con un tapacete adecuado.','No, nunca'], correcta:1 },
  { id:'t3-41', tema:3, n:41, q:'¿Está autorizado a circular un vehículo cargado cuando transporte sustancia o residuos malolientes de cualquier clase?', opciones:['No, nunca','Sí, siempre','A veces, si el vehículo es cerrado o están en recipientes herméticamente cerrados.'], correcta:2 },
  { id:'t3-42', tema:3, n:42, q:'Usted, como conductor de un vehículo dedicado al transporte de carga, al trasladar cargas que sobresalgan de su cama o caja más de un metro por delante o por detrás, deberá señalar la carga en su parte más sobresaliente, de forma tal que las señales puedan ser advertidas claramente a una distancia de:', opciones:['50 metros como mínimo','100 metros como mínimo.','80 metros como mínimo'], correcta:1 },
  { id:'t3-43', tema:3, n:43, q:'Cuando usted conduzca un vehículo de carga, solo o en caravana, deberá:', opciones:['Llevar encendidas las luces altas o largas, en el horario comprendido entre el atardecer y el anochecer.','Que viaje un compañero responsable en la cabina y otro en la cama del camión','Que el vehículo posea techo'], correcta:0 },
  { id:'t3-44', tema:3, n:44, q:'Cuando usted conduzca un vehículo de carga que circule en caravana, deberá observar reglas siguientes:', opciones:['La distancia entre vehículos en marcha no excederá los 10 metros cuando circule por una vía urbana ni los 15 metros cuando transite por una vía rural','La velocidad será de 70 kilómetros por hora','El jefe o responsable de la caravana viajará en la cabina del primer vehículo o guía de la caravana.'], correcta:2 },
  { id:'t3-45', tema:3, n:45, q:'Cuando usted conduzca un vehículo que circule en caravana, deberá observar determinadas reglas:', opciones:['La distancia entre vehículos durante la marcha no será inferior a los 5 metros por cada 15 kilómetros por hora de velocidad.','El jefe o responsable de la caravana viajará en la cabina del último vehículo, para mantener el control del desplazamiento','No permitirá que las personas lleven bolsos'], correcta:0 },
  { id:'t3-46', tema:3, n:46, q:'Cuando usted conduzca un vehículo de carga que circule en caravana, deberá observar determinadas reglas:', opciones:['Sonar permanentemente el claxon para avisar que se desplaza una caravana','No podrá adelantar al vehículo que le precede, salvo en casos de fuerza mayor.','Llevar las luces de carretera o larga, en las horas comprendidas entre el atardecer y el anochecer, al circular por carreteras o autopistas'], correcta:1 },
  { id:'t3-47', tema:3, n:47, q:'Cuando usted conduzca un vehículo de carga que circule en caravana, deberá observar determinadas reglas:', opciones:['Sonar el claxon con regularidad para avisar que se aproxima una caravana','Que los vehículos estén techados, para proteger a los pasajeros','Llevar encendidas las luces de cruce o cortas, en horas del día.'], correcta:2 },
  { id:'t3-48', tema:3, n:48, q:'Cuando usted conduzca un vehículo que circule en caravana, deberá observar determinadas reglas:', opciones:['No adelantará a otro vehículo en la vía, a menos que este se encuentre detenido o que su velocidad sea inferior a los vehículos que circulan en caravana.','El jefe o responsable de la caravana viajará en la cabina del último vehículo, para mantener el control del desplazamiento','Las personas que transporta podrán sentarse en las barandas cuando no existan bancos'], correcta:0 },
  { id:'t3-49', tema:3, n:49, q:'Cuando usted conduzca un vehículo que circule en caravana, deberá observar determinadas reglas:', opciones:['Durante la marcha, la distancia entre vehículos será de 5 metros por cada 10 kilómetros por hora de velocidad','Al llegar al lugar de destino, deberá apartarse, de ser posible, de la calzada o camino para bajar el personal.','La velocidad debe ser en zona urbana de 45 kilómetros por hora'], correcta:1 },
  { id:'t3-50', tema:3, n:50, q:'Cuando usted conduzca un vehículo que circule en caravana, deberá observar determinadas reglas:', opciones:['De considerarlo necesario, el organismo responsable de la organización de la caravana designará a un compañero responsable para que viaje en la cama del último vehículo','Llevar encendidas las luces de carretera o largas, en las horas del día','No permitirá que las personas se bajen del vehículo hasta que este se haya detenido en el área prevista para ello.'], correcta:2 },
  { id:'t3-51', tema:3, n:51, q:'Cuando usted conduzca un vehículo que circule en caravana, deberá observar determinadas reglas:', opciones:['Al llegar al lugar de destino, los responsables de la caravana detendrán el tránsito, si fuera necesario, cuando las personas transportadas requieran atravesar a pie una vía.','No podrá adelantar a otro vehículo en la vía, salvo que este circule a una velocidad inferior a 50 kilómetros por hora en zona urbana y 80 kilómetros por hora en zona rural','La distancia entre vehículos será de 10 metros'], correcta:0 },
  { id:'t4-01', tema:4, n:1, q:'A que distancia de la línea férrea el conductor está obligado a detener la marcha:', opciones:['A menos de 10 metros','En la vertical correspondiente','A no menos de 3metros de la primera línea'], correcta:2 },
  { id:'t4-02', tema:4, n:2, q:'Cuando usted está obligado a disminuir y parar si preciso fuera:', opciones:['Ante la señal de pare','Ante la señal de agente de orden publico','En los tramos de la calzada que presenten estrechamiento'], correcta:2 },
  { id:'t4-03', tema:4, n:3, q:'En los lugares que no existan señales de prioridad el conductor está obligado a:', opciones:['Detener la marcha','Aminorar la velocidad cuando el peatón está en la vía','En calzadas de doble sentido de circulación ceder el paso a los vehículos que circulan en sentido opuesto cuando realiza un giro a la izquierda'], correcta:2 },
  { id:'t4-04', tema:4, n:4, q:'Usted, en su condición de conductor de cualquier vehículo de motor debe tener en cuenta que las vías que no tengan señalizado su sentido de dirección se consideran de:', opciones:['Doble sentido de circulación.','Un solo sentido de dirección','Es un error de señalización'], correcta:0 },
  { id:'t4-05', tema:4, n:5, q:'Cómo conductor de un vehículo de motor, al incorporarse a una vía de un solo sentido de dirección, ante la señal de "Pare", usted está obligado a:', opciones:['Detener la marcha solo si no hay visibilidad','Disminuir la velocidad y parar si fuera necesario','Detener la marcha ante la señal y darle prioridad a los vehículos que circulan por la vía transversal.'], correcta:2 },
  { id:'t4-06', tema:4, n:6, q:'Circulando por una vía de un solo sentido de dirección, al aproximarse a una intersección con la señal de "Ceda el paso", está usted obligado a:', opciones:['Detener la marcha en cualquier caso','Disminuir la velocidad y parar si fuera necesario.','Continuar con precaución'], correcta:1 },
  { id:'t4-07', tema:4, n:7, q:'Cuando al circular por una vía, usted requiere realizar el cruce de otra vía con igual categoría, en una intersección donde no exista señal que indique la prioridad, está obligado a:', opciones:['Disminuir la velocidad y parar si fuera necesario, a fin de permitir el paso a todos los vehículos que se aproximan por la vía transversal por el lado izquierdo','Ceder el paso o detenerse si es necesario, ante el vehículo que por la vía transversal se aproxima por su lado derecho.','Ceder el paso a los vehículos que se aproximan en sentido opuesto, por la misma vía'], correcta:1 },
  { id:'t4-08', tema:4, n:8, q:'Circulando por una vía de un solo sentido de dirección, usted requiere incorporarse a una vía de doble sentido, en una intersección donde no existe señal que indica la prioridad de las vías. Para ello está obligado a:', opciones:['Detener la marcha en cualquier caso','Ceder el paso o detenerse si es necesario, ante el vehículo que se aproxima por la vía transversal en cualquier dirección.','Ceder el paso solo ante el vehículo que por la vía transversal se aproxima por su lado derecho'], correcta:1 },
  { id:'t4-09', tema:4, n:9, q:'Circulando por una vía de doble sentido de circulación, usted pretende doblar a la izquierda, para incorporarse a otra. Para ello está obligado a:', opciones:['Dejar que pasen los vehículos que circulan detrás del suyo','Ceder el paso o detenerse si es necesario, ante el vehículo que por la vía transversal se aproxima por su lado izquierdo','Ceder el paso a los vehículos que se aproximan en sentido opuesto por la misma vía.'], correcta:2 },
  { id:'t4-10', tema:4, n:10, q:'El conductor de un vehículo al salir de un estacionamiento, parqueo o acceso, con la pretensión de incorporarse o cruzar una vía y cuando no exista señal alguna que establezca la conducta a seguir, está obligado a:', opciones:['Ceder el paso solo los vehículos que se aproximan por la derecha en la vía transversal','Detener la marcha, cualesquiera que sean las circunstancias de visibilidad','Ceder el paso a los vehículos que se aproximan por la vía transversal en ambos sentidos.'], correcta:2 },
  { id:'t4-11', tema:4, n:11, q:'El conductor de un vehículo al circular por una vía no pavimentada, con la pretensión de incorporarse o cruzar una vía pavimentada, cuando no exista señal alguna que establezca la conducta a seguir, está obligado a:', opciones:['Detener la marcha, cualesquiera que sean las circunstancias de visibilidad','Ceder el paso a los vehículos que se aproximan por la vía transversal.','Ceder el paso solo a los vehículos que se aproximan por el lado derecho'], correcta:1 },
  { id:'t4-12', tema:4, n:12, q:'Al aproximarse a un paso a nivel sin señalización el conductor de cualquier vehículo, está obligado a:', opciones:['Ceder el paso','Disminuir la velocidad','Detener la marcha.'], correcta:2 },
  { id:'t4-13', tema:4, n:13, q:'Al aproximarse a un paso a nivel con guardabarreras u otras señales sonoras o lumínicas, el conductor de cualquier vehículo está obligado a:', opciones:['Moderar la velocidad y tomar precauciones.','Detener la marcha','Ceder el paso'], correcta:0 },
  { id:'t4-14', tema:4, n:14, q:'Conduciendo cualquier vehículo, al observar peatones que empiecen a cruzar o se encuentren cruzando la calzada por lugares con las marcas y señales previstos, usted está obligado a:', opciones:['Disminuir velocidad','Accionar el claxon o aparato similar','Detener el vehículo y ceder el paso.'], correcta:2 },
  { id:'t4-15', tema:4, n:15, q:'El conductor de cualquier vehículo de motor está obligado a moderar la velocidad y detener la marcha, si preciso fuere:', opciones:['Para facilitar la maniobra de adelantamiento de otro vehículo','Frente a los lugares de espectáculos públicos, a la hora de entrada y salida del público.','Al aproximarse a la entrada de túneles, puentes, pasos superiores, inferiores e intercambios'], correcta:1 },
  { id:'t4-16', tema:4, n:16, q:'El conductor de cualquier vehículo de motor está obligado a moderar la velocidad y detener la marcha, si preciso fuere:', opciones:['Al acercarse a un rebaño de animales.','Para hacer uso de teléfonos u otros medios de comunicación, cualesquiera que sean sus características','A menos de 150 metros anteriores a la entrada de una curva de visibilidad reducida, que no permita ver la continuación de la vía'], correcta:0 },
  { id:'t4-17', tema:4, n:17, q:'El conductor de cualquier vehículo de motor está obligado a moderar la velocidad y detener la marcha, si preciso fuere:', opciones:['Al aproximarse a una señal de "PARE", indicada por la preseñalización correspondiente','Ante el vehículo que se aproxima por la vía transversal, por su lado izquierdo, en vías de igual categoría','En los tramos de las calzadas que presentan estrechamiento.'], correcta:2 },
  { id:'t4-18', tema:4, n:18, q:'El conductor de cualquier vehículo de motor está obligado a moderar velocidad y detener la marcha, si preciso fuere:', opciones:['Para realizar cualquier maniobra de giro, siempre que las condiciones físicas de la vía lo requieran','En los casos de niebla densa, lluvia copiosa, nubes de humo o de polvo.','A menos de 150 metros anteriores a un cambio de rasante, que no permita ver la continuación de la vía'], correcta:1 },
  { id:'t4-19', tema:4, n:19, q:'El conductor de cualquier vehículo de motor está obligado a moderar la velocidad y detener la marcha, si preciso fuere:', opciones:['Cuando la superficie de la vía está resbaladiza por la presencia de agua, grasa, arena, lodo u otras sustancias similares.','Al aproximarse a una zona oficial','Ante el vehículo que se aproxima en sentido opuesto, por la misma vía, en vías de igual categoría'], correcta:0 },
  { id:'t4-20', tema:4, n:20, q:'El conductor de cualquier vehículo de motor está obligado a moderar la velocidad y detener la marcha, si preciso fuere:', opciones:['Al circular por una ciclovía o ciclocarril','Al aproximarse a una curva muy peligrosa','Cuando algún ómnibus de transporte de pasajeros se está deteniendo o se encuentra detenido.'], correcta:2 },
  { id:'t4-21', tema:4, n:21, q:'El conductor de cualquier vehículo de motor está obligado a moderar la velocidad y detener la marcha, si preciso fuere:', opciones:['Al transitar por una vía preferencial','Cuando un peatón se encuentre en la calzada.','Frente a las unidades de la Policía Nacional Revolucionaria'], correcta:1 },
  { id:'t4-22', tema:4, n:22, q:'El conductor de cualquier vehículo de motor está obligado a moderar la velocidad y detener la marcha, si preciso fuere:', opciones:['En una intersección o al cruzar o incorporarse a una vía transversal.','Ante el vehículo que se aproxima por la vía transversal, por su lado izquierdo, en vías de igual categoría','Al aproximarse a una señal de "Prohibición de Parqueo"'], correcta:0 },
  { id:'t4-23', tema:4, n:23, q:'El conductor de cualquier vehículo de motor está obligado a moderar la velocidad y detener la marcha, si preciso fuere:', opciones:['Al transitar por una zona urbana','Al transitar por una autopista','Cuando la persona que guía un grupo de niños se lo indica para permitirles el cruce por la vía.'], correcta:2 },
  { id:'t4-24', tema:4, n:24, q:'El conductor de cualquier vehículo de motor está obligado a moderar la velocidad y detener la marcha, si preciso fuere:', opciones:['Al circular por una vía de doble sentido normalmente','Ante la presencia de un vehículo con el rótulo de impedido físico.','Al aproximarse a una zona de niños en zona urbana en días y horas no laborables'], correcta:1 },
  { id:'t4-25', tema:4, n:25, q:'¿Cuándo deben estar equipados con un claxon o aparato similar los vehículos de motor o ciclos?', opciones:['Nunca','Siempre.','A veces'], correcta:1 },
  { id:'t4-26', tema:4, n:26, q:'¿Cuándo está prohibido usar el claxon o aparato similar en las poblaciones?', opciones:['Sí, siempre, ya que está permitido totalmente','No, nunca, ya que está prohibido','Sí, a veces, en las excepciones previstas por la Ley.'], correcta:2 },
  { id:'t5-01', tema:5, n:1, q:'Que conducta debe seguir un conductor en el momento de recoger un pasajero:', opciones:['Recogerlo desde la senda del medio','Tener el vehículo detenido por 5 minutos','Emprender nuevamente la marca cuando todos los pasajeros hallan subido o bajado del vehículo'], correcta:2 },
  { id:'t5-02', tema:5, n:2, q:'Donde está prohibido el estacionamiento o parqueo de vehículos:', opciones:['A más de 100 metros de una intersección semaforizada','Dentro de las ballas del parqueo','En las aceras, paseos o césped'], correcta:2 },
  { id:'t5-03', tema:5, n:3, q:'Cuando está prohibido parquear en el espacio de 40 metros hacia atrás y 10 metros hacia delante de la señal de paradas de ómnibus:', opciones:['No nunca','A veces si no hay ómnibus','Si siempre'], correcta:2 },
  { id:'t5-04', tema:5, n:4, q:'Donde se realiza el estacionamiento en calzadas de una dirección', opciones:['Junto a la acera o borde derecho y en el sentido de la circulación','Junto a la acera o borde izquierdo y en el sentido de circulación','De forma trasversal al sentido de circulación'], correcta:1 },
  { id:'t5-05', tema:5, n:5, q:'Puede un conductor de vehículo de motor dejar a un pasajero en una curva de visibilidad reducida:', opciones:['Si, a veces, por la noche','Si, siempre','No, nunca'], correcta:2 },
  { id:'t5-06', tema:5, n:6, q:'¿Dónde se realiza el estacionamiento en calzadas de dos direcciones?', opciones:['Paralelo a la dirección de la circulación y junto a la acera y borde de la derecha.','Paralelo a la dirección de la circulación y junto a la acera y borde de la izquierda','De forma transversal a la vía'], correcta:0 },
  { id:'t5-07', tema:5, n:7, q:'¿Dónde se realiza el estacionamiento en calzadas de una dirección?', opciones:['Junto a la acera o borde derecho y en el sentido de la circulación','Junto a la acera o borde izquierdo y en el sentido de la circulación.','De forma oblicua a la vía'], correcta:1 },
  { id:'t5-08', tema:5, n:8, q:'¿Qué distancia debe de existir entre las ruedas y el contén de la acera cuando se realiza el estacionamiento?', opciones:['20 centímetros','15 centímetros','Hasta 10 centímetros.'], correcta:2 },
  { id:'t5-09', tema:5, n:9, q:'¿Qué distancia debe de existir entre dos vehículos en estacionamientos?', opciones:['Más de 50 centímetros.','40 centímetros','45 centímetros'], correcta:0 },
  { id:'t5-10', tema:5, n:10, q:'¿Es obligatorio parquear en la forma que se indica en la zona de la vía donde existan marcas, señales y contén?', opciones:['No, nunca','Sí, siempre.','Sí, a veces'], correcta:1 },
  { id:'t5-11', tema:5, n:11, q:'¿Es obligatorio parquear dentro de la valla del parqueo sin sobresalir sus límites, en estacionamientos paralelos o no a la circulación?', opciones:['No, nunca','Si, a veces','Si, siempre.'], correcta:2 },
  { id:'t5-12', tema:5, n:12, q:'¿Cuándo se prohíbe parquear en la acera?', opciones:['Siempre.','Nunca','A veces, para evitar obstrucciones'], correcta:0 },
  { id:'t5-13', tema:5, n:13, q:'¿Cuándo se puede parquear en una zona de carga?', opciones:['Siempre','A veces, excepto en los días y horas establecidas para las operaciones de carga y descarga.','Nunca'], correcta:1 },
  { id:'t5-14', tema:5, n:14, q:'¿Cuándo se prohíbe parquear en el espacio de 20 metros hacia atrás y 10 metros hacia delante de la señal oficial de parada de ómnibus?', opciones:['A veces, para tomar pasajeros','Nunca','Siempre.'], correcta:2 },
  { id:'t5-15', tema:5, n:15, q:'¿Cuándo se prohíbe parquear en el espacio que comprende una zona de piquera de automóviles de alquiler?', opciones:['A veces, en los días y horas en que se preste este servicio.','Siempre','Nunca'], correcta:0 },
  { id:'t5-16', tema:5, n:16, q:'¿Está prohibido parquear en la parte de la vía que circundan las islas o rotondas situadas en la confluencia de las vías?', opciones:['No, nunca','Sí, siempre.','Sí, a veces'], correcta:1 },
  { id:'t5-17', tema:5, n:17, q:'¿Está prohibido parquear en la entrada o salida de garajes, pistas y rampas o en cualquier lugar y forma que obstruyan la vía en las intersecciones?', opciones:['No, nunca','Si, a veces','Si, siempre.'], correcta:2 },
  { id:'t5-18', tema:5, n:18, q:'¿Cuándo está prohibido parquear entre una zona de seguridad y la acera?', opciones:['Siempre.','Nunca','A veces'], correcta:0 },
  { id:'t5-19', tema:5, n:19, q:'¿Cuándo está prohibido parquear entre dos zonas de seguridad?', opciones:['A veces','Siempre.','Nunca'], correcta:1 },
  { id:'t5-20', tema:5, n:20, q:'¿Cuándo está prohibido parquear en el espacio comprendido entre las dos líneas longitudinales continuas marcadas en el pavimento y que separan los sentidos de circulación...?', opciones:['Nunca','A veces, cuando no hay otro espacio','Siempre.'], correcta:2 },
  { id:'t5-21', tema:5, n:21, q:'¿Cuándo está prohibido parquear en zonas oficiales, de embajadas o consulados?', opciones:['Siempre.','A veces, cuando no hay otro lugar','Nunca'], correcta:0 },
  { id:'t5-22', tema:5, n:22, q:'¿Está prohibido parquear a una distancia menor de cuatro metros, anteriores y posteriores, de un hidrante?', opciones:['Sí, a veces, si no hay más espacio','Sí, siempre.','No, nunca'], correcta:1 },
  { id:'t5-23', tema:5, n:23, q:'¿Está prohibido parquear en el frente y costado de las unidades de los ministerios del Interior y de las Fuerzas Armadas Revolucionarias?', opciones:['Sí, a veces, por seguridad','No, nunca','Sí, siempre.'], correcta:2 },
  { id:'t5-24', tema:5, n:24, q:'¿Está prohibido parquear en el frente o a la entrada principal de edificios públicos?', opciones:['Cuando obstrucciones o dificulte la entrada y salida de estos.','Sí, siempre','No, nunca'], correcta:0 },
  { id:'t5-25', tema:5, n:25, q:'¿Está prohibido parquear en los puentes, túneles, pasos superiores o inferiores, intercambios y sus accesos?', opciones:['Sí, a veces, por falta de espacio','Sí, siempre.','No, nunca'], correcta:1 },
  { id:'t5-26', tema:5, n:26, q:'¿Puede recogerse pasajeros en los puentes, túneles, pasos superiores o inferiores, intercambios y sus accesos?', opciones:['Sí, a veces, cuando hay poco tránsito','Sí, siempre','No, nunca.'], correcta:2 },
  { id:'t5-27', tema:5, n:27, q:'¿Puedo dejar un pasajero en una curva de visibilidad reducida?', opciones:['Sí, a veces, por la noche','Sí, siempre','No, nunca.'], correcta:2 },
  { id:'t5-28', tema:5, n:28, q:'¿Puedo dejar un pasajero en un cambio de rasante que oculte la visibilidad de la vía?', opciones:['No, nunca.','Sí, a veces, cuando hay poco tránsito','Sí, siempre'], correcta:0 },
  { id:'t5-29', tema:5, n:29, q:'¿Puede estacionarse un conductor en ciclovías, ciclocarriles o vías exclusivas?', opciones:['Sí, a veces, cuando es de madrugada y hay poco tránsito','No, nunca.','Sí, siempre'], correcta:1 },
  { id:'t5-30', tema:5, n:30, q:'¿Puedo estacionar en la parte destinada a la circulación en las vías rurales?', opciones:['No, nunca.','Sí, a veces, por fuerza mayor','Sí, siempre'], correcta:0 },
  { id:'t5-31', tema:5, n:31, q:'¿Cuándo se aplica el freno de mano o seguridad al estacionar un vehículo en la vía autorizada para ello?', opciones:['Siempre.','Nunca','A veces, en pendientes'], correcta:0 },
  { id:'t5-32', tema:5, n:32, q:'¿Cuándo al estacionar un vehículo en la vía se aplica la primera velocidad y se gira el volante del timón en sentido contrario del contén?', opciones:['En pendientes descendentes','En pendiente ascendente.','En terreno llano'], correcta:1 },
  { id:'t5-33', tema:5, n:33, q:'¿Cuándo al estacionar un vehículo en la vía se debe aplicar la velocidad para marcha atrás y girar el volante del timón hacia el contén...?', opciones:['En terreno llano','En pendiente ascendente','En pendiente descendente.'], correcta:2 },
  { id:'t5-34', tema:5, n:34, q:'¿Cuándo al estacionar un vehículo en vía urbana o rural donde no exista contén se deben calzar las ruedas o gomas traseras o delanteras del vehículo?', opciones:['En pendiente ascendente o descendiente.','Solo en pendiente ascendente','Solo en pendiente descendente'], correcta:0 },
  { id:'t5-35', tema:5, n:35, q:'Conduciendo por una vía decide detenerse para recoger a una persona que le hace señas, para hacerlo con seguridad, usted está obligado a:', opciones:['Emprender nuevamente la marcha cuando la persona haya terminado de subir y la puerta se encuentre debidamente cerrada.','Mantener el vehículo detenido por no menos de tres minutos','Realizar la detención en cualquier carril'], correcta:0 },
  { id:'t8-01', tema:8, n:1, q:'Todos los conductores profesionales están obligados a recalificarse:', opciones:['Si todos','A los conductores de 65 años de edad','Cuando existen motivos fundados en su expediente'], correcta:0 },
  { id:'t8-02', tema:8, n:2, q:'Que sucede si dentro del tiempo de la suspensión de la licencia de conducción circula por la vía en un vehículo de motor', opciones:['Suspensión de la licencia de conducción','Privación de libertad','Cancelación de la licencia de conducción'], correcta:2 },
  { id:'t8-03', tema:8, n:3, q:'Que sucede si usted realiza una reclamación de una multa y esta es declarada con lugar:', opciones:['Le suspenden la licencia','Le quitan los puntos','Le devuelven el importe y le retiran los puntos'], correcta:2 },
  { id:'t8-04', tema:8, n:4, q:'Queda prohibida la ingestión y transportación de bebidas alcohólicas en los compartimientos destinados al conductor y a los pasajeros:', opciones:['A veces en dependencia de la bebida','No nunca','Si siempre'], correcta:2 },
  { id:'t8-05', tema:8, n:5, q:'El Ministerio del Interior puede disponerla suspensión de la licencia de conducción de un mes a tres meses a:', opciones:['Los conductores profesionales que acumulen 36 puntos','Los titulares que transcurrido el plazo de 60 días naturales de impuesta no haya abonado su importe','Los titulares que habiendo presentado los exámenes médicos realizados al Órgano de Licencia de Conducción a los 65 años de edad no los presenten al cumplir dos años mas'], correcta:0 },
  { id:'t8-06', tema:8, n:6, q:'Cuando un conductor cometa una infracción del transito conduciendo un vehículo de uso personal, i haya ingerido bebidas alcohólicas:', opciones:['Será sancionado administrativamente por el órgano del Ministerio del Interior con la suspensión de la licencia de conducción por un `periodo no menor de 30 días ni mayor de 90','Se le duplicara el importe de la multa correspondiente a la infracción','Será sancionado administrativamente por el órgano de Ministerio del Interior con la cancelación de la licencia de conducción'], correcta:1 },
  { id:'t8-07', tema:8, n:7, q:'El conductor de un vehículo de carga o transporte colectivo, es sorprendido violando la señal de PARE y ha ingerido bebidas alcohólicas, sin afectar la capacidad para conducir, que medida se aplica:', opciones:['Solamente se le duplicara el importe de la multa correspondiente a la infracción','Se le suspenderá la licencia de conducción y se le duplicará el importe de la multa','Se le cancelara la licencia de conducción'], correcta:1 },
  { id:'t8-08', tema:8, n:8, q:'Cuando un conductor cometa una infracción del tránsito conduciendo un vehículo de uso personal, y haya ingerido bebidas alcohólicas:', opciones:['Será sancionado administrativamente por el órgano del Ministerio del Interior con la suspensión de la licencia de conducción por un período no menor de 30 días ni mayor de 90','Se le duplicará el importe de la multa correspondiente a la infracción cometida.','Será sancionado administrativamente por el órgano del Ministerio del Interior con la cancelación de la licencia de conducción'], correcta:1 },
  { id:'t8-09', tema:8, n:9, q:'Si el conductor de un vehículo de uso personal es sorprendido violando la señal de "PARE" y ha ingerido bebidas alcohólicas, sin afectar su capacidad de conducir, -¿Qué medida se le aplica?', opciones:['Se le duplicará el importe de la multa correspondiente a la infracción cometida.','Se le suspenderá la licencia de conducción por un mes','Se le impondrá una advertencia'], correcta:0 },
  { id:'t8-10', tema:8, n:10, q:'Cuando el conductor de un vehículo de carga, de transporte colectivo de pasajeros o profesional que actúe como tal, sea detectado conduciendo después de haber ingerido bebidas alcohólicas será sancionado administrativamente por el órgano correspondiente del Ministerio del Interior con:', opciones:['La suspensión de la licencia de conducción por un período no menor de 90 días ni mayor de un año. Sí además, comete una infracción del tránsito se le duplicará el importe de la multa correspondiente a la infracción cometida','La suspensión de la licencia de conducción por un período de un mes y se le duplicará el importe de la multa correspondiente a la infracción cometida.','La cancelación de la licencia de conducción'], correcta:1 },
  { id:'t8-11', tema:8, n:11, q:'Si el conductor de un vehículo de carga o trasporte colectivo de pasajeros es sorprendido violando la señal de "PARE" y ha ingerido bebidas alcohólicas, sin afectar su capacidad de conducir, -¿Qué medida se le aplica?', opciones:['Solamente se le duplicará el importe de la multa correspondiente a la infracción cometida','Se le suspenderá la licencia de conducción por un período no menor de 180 días ni mayor de un año y se le duplicará el importe de la multa correspondiente a la infracción cometida.','Se le cancelará la licencia de conducción'], correcta:1 },
  { id:'t8-12', tema:8, n:12, q:'Si un conductor profesional es sorprendido con ingestión de bebidas alcohólicas, sin afectar su capacidad de conducir y sin otra violación -¿Qué medida se le aplica?', opciones:['Se le cancela la licencia de conducción','Solo se le duplicará el importe de la multa correspondiente a la infracción cometida','Se le suspenderá la licencia de conducción de 180 días a un año.'], correcta:2 },
  { id:'t8-13', tema:8, n:13, q:'Usted, como conductor de cualquier vehículo de motor, debe tener presente que las regulaciones del tránsito prohíben conducir o permitir que otro conduzca:', opciones:['Cualquier vehículo destinado a carga o transporte colectivo de pasajeros cuando haya ingerido bebidas alcohólicas, sin que afecte su capacidad de conducir.','Un vehículo de uso personal cuando haya ingerido bebidas alcohólicas, sin que afecte su capacidad para conducir','Con defectos físicos y portando documento de autorización'], correcta:0 },
  { id:'t8-14', tema:8, n:14, q:'Usted debe tener presente que las regulaciones del tránsito prohíben conducir o permitir que otro conduzca:', opciones:['A un chofer profesional que no actúa como tal, después de haber ingerido bebidas alcohólicas, en su auto','Cualquier vehículo de uso personal, cuando haya ingerido bebidas alcohólicas y no se afecte su capacidad para conducir','Cuando haya ingerido bebidas alcohólicas, en todos los casos que el conductor actúe en su condición de chofer profesional.'], correcta:2 },
  { id:'t8-15', tema:8, n:15, q:'Como conductor de cualquier vehículo de motor, usted debe conocer que el Ministerio del Interior podrá disponer la suspensión de la licencia de conducción por un período de un mes hasta un año, a los titulares que:', opciones:['En el período de un año natural cometan más de dos infracciones de las regulaciones del tránsito, calificadas como "muy peligrosas".','En los dos últimos años naturales se les suspenda la licencia de conducción, administrativa o judicialmente, en más de dos ocasiones','En una ocasión, en el período de un año natural, conduzcan un vehículo sin las correspondientes chapas de identificación, expedidas por el Registro de Vehículos'], correcta:0 },
  { id:'t8-16', tema:8, n:16, q:'Como conductor de cualquier vehículo de motor, usted debe conocer que el Ministerio del Interior podrá disponer la suspensión de la licencia de conducción por un período de un mes hasta un año, a los titulares que:', opciones:['Siendo conductores profesionales no aprueben la reevaluación obligatoria en el período dispuesto por los organismos rectores','En el período de un año natural, después de haber cumplido una suspensión administrativa o judicial de la licencia de conducción, incurra en una nueva infracción calificada como "muy peligrosa"','En el período de un año natural alcancen la puntuación determinada por el Ministerio del Interior (más de 36 puntos).'], correcta:2 },
  { id:'t8-17', tema:8, n:17, q:'¿Está establecido que todos los choferes profesionales realicen la recalificación y reevaluación cada cierto tiempo?', opciones:['No, sólo los del Ministerio del Transporte','No, sólo los mayores de 65 años','Sí, todos.'], correcta:2 },
  { id:'t8-18', tema:8, n:18, q:'Como conductor de cualquier vehículo de motor, usted debe conocer que el Ministerio del Interior podrá disponer la suspensión de la licencia de conducción por un período de un mes hasta un año, a los titulares que:', opciones:['Durante el tiempo de suspensión de la licencia de conducción se detecten conduciendo un vehículo de motor por la vía pública','En el período de un año natural, cometan más de una infracción del tránsito conduciendo un vehículo de uso personal, después de haber ingerido bebidas alcohólicas.','Siendo conductores profesionales, en más de una ocasión, durante un período de un año natural, se les suspenda la licencia de conducción después de haber ingerido bebidas alcohólicas'], correcta:1 },
  { id:'t8-19', tema:8, n:19, q:'Como conductor de cualquier vehículo de motor, usted debe conocer que el Ministerio del Interior podrá disponer la cancelación de la licencia de conducción a los titulares que:', opciones:['En los dos últimos años naturales se les suspenda la licencia de conducción, administrativa o judicialmente, en más de dos ocasiones.','En el período de un año natural, cometan más de dos infracciones de las regulaciones del tránsito calificadas como "muy peligrosas"','Durante el período de un año tengan más de 36 puntos'], correcta:0 },
  { id:'t8-20', tema:8, n:20, q:'Como conductor de cualquier vehículo de motor, usted debe conocer que el Ministerio del Interior podrá disponer la cancelación de la licencia de conducción a los titulares que:', opciones:['Siendo conductores profesionales tengan más de 36 puntos','Adiestran aspirantes a licencia de conducción durante el período de vigencia del permiso de aprendizaje, incumpliendo las regulaciones establecidas para ello.','En el período de un año natural, después de haber cumplido el tiempo de sanción dispuesto para la suspensión de la licencia de conducción administrativa o judicialmente, incurran en una nueva infracción calificada como "muy peligrosa"'], correcta:1 },
  { id:'t8-21', tema:8, n:21, q:'Como conductor de cualquier vehículo de motor, usted debe conocer que el Ministerio del Interior podrá disponer la cancelación de la licencia de conducción por un período que puede oscilar entre tres y cinco años, a los titulares que:', opciones:['En un año natural, cometan más de tres infracciones del primer grupo','Durante el período de suspensión de la licencia de conducción, circulen por la vía conduciendo un vehículo de motor.','Siendo conductores profesionales, en más de una ocasión, durante un año natural, se les suspenda la licencia de conducción por conducir después de haber ingerido bebidas alcohólicas'], correcta:1 },
  { id:'t8-22', tema:8, n:22, q:'Como conductor de cualquier vehículo de motor, usted debe conocer que el Ministerio del Interior podrá disponer la cancelación de la licencia de conducción los titulares que:', opciones:['Siendo conductores de vehículos de carga o transporte de pasajeros, en más de una ocasión, durante un período de tres años naturales, se les suspenda la licencia de conducción por conducir después de haber ingerido bebidas alcohólicas.','En un año natural cometan más de cuatro infracciones del primer grupo','En más de una ocasión en el período de un año natural, conduzcan un vehículo de motor sin las correspondientes chapas de identificación expedidas por el Registro de Vehículos'], correcta:0 },
  { id:'t8-23', tema:8, n:23, q:'Como conductor de cualquier vehículo de motor, usted debe conocer que el Ministerio del Interior podrá disponer la cancelación de la licencia de conducción a los titulares que:', opciones:['Durante un período de tres años naturales, después de habérseles suspendido la licencia de conducción administrativa o judicialmente, incurran en una nueva infracción calificada como "muy peligrosa"','Siendo conductores profesionales tengan 5 infracciones del primer grupo','En su condición de conductor profesional y actuando como tal, en más de una ocasión, durante un período de tres años naturales, se les suspenda la licencia de conducción por conducir después de haber ingerido bebidas alcohólicas.'], correcta:2 },
  { id:'t8-24', tema:8, n:24, q:'Usted, como aspirante a obtener la licencia de conducción, debe conocer que el Ministerio del Interior podrá disponer la cancelación de su permiso de aprendizaje:', opciones:['Cuando conduzca un vehículo de motor sin la compañía de un titular que posea 3 años de experiencia en la categoría a la que se aspira.','Cuando cumpliendo las regulaciones establecidas para el aprendizaje, cometa una infracción del tránsito','Cuando cometa más de dos infracciones de las regulaciones del tránsito calificadas como "muy peligrosas"'], correcta:0 },
  { id:'t8-25', tema:8, n:25, q:'Como conductor de cualquier vehículo de motor, usted debe conocer que el Ministerio del Interior podrá disponer la suspensión de la licencia de conducción a los titulares que:', opciones:['En el período de un año natural cometan una infracción de las regulaciones del tránsito calificadas como "muy peligrosas", conduciendo un vehículo de uso personal, después de haber ingerido bebidas alcohólicas','En más de una ocasión, dentro de un año natural, conduzcan un vehículo sin las correspondientes chapas de identificación expedidas por el Registro de Vehículos.','En su condición de conductor profesional y actuando como tal le impongan 6 multas del primer grupo'], correcta:1 },
  { id:'t8-26', tema:8, n:26, q:'Usted, como conductor de cualquier vehículo de motor, debe conocer que el Ministerio del Interior podrá disponer la cancelación de la licencia de conducción a los conductores profesionales que:', opciones:['En una ocasión, durante un año natural, cometa una infracción de las regulaciones del tránsito, después de haber ingerido bebidas alcohólicas','Sean detectados conduciendo un vehículo de motor por la vía pública sin chapas','No aprueben la reevaluación obligatoria en el período que se disponga.'], correcta:2 },
  { id:'t8-27', tema:8, n:27, q:'¿Podrán disponer la suspensión de la licencia de conducción cuando no haya hecho efectivo el pago de una multa, transcurrido el plazo de sesenta días naturales desde su fecha de imposición?', opciones:['Sí, por dos meses','Sí, por un período de un mes a tres meses.','No'], correcta:1 },
  { id:'t8-28', tema:8, n:28, q:'¿Que puede pasar, si cumplido el tiempo de una suspensión de licencia de conducción dispuesta por morosidad en el pago de una multa de tránsito, no se ha realizado el pago de la multa en la cuantía que corresponda?', opciones:['Advertencia, y pagar triple','Suspensión','Cancelación.'], correcta:2 },
  { id:'t8-29', tema:8, n:29, q:'Usted, como titular de licencia de conducción, debe conocer que el pago de una multa sin recargo, por infracción de las regulaciones del tránsito, se realizará:', opciones:['Dentro de los treinta días naturales siguientes a la notificación de la infracción.','En un plazo de veinte días naturales, siguientes a la notificación de la infracción','En los setenta días naturales posteriores a la notificación de la infracción'], correcta:0 },
  { id:'t8-30', tema:8, n:30, q:'¿Qué sucede si el pago de una multa se efectúa después de transcurrido el plazo de treinta días naturales siguientes a la notificación, sin exceder los sesenta?', opciones:['El importe de la multa se triplica','El importe de la multa se mantiene, pero le ocupan la licencia','El importe de la multa se duplica.'], correcta:2 },
  { id:'t8-31', tema:8, n:31, q:'En el acto de imposición de una multa, el conductor deberá firmar la boleta en presencia de la autoridad que la impone -¿Qué significa esta firma?', opciones:['Que reconoce su responsabilidad en la contravención','Una constancia del acto de imposición.','Que ya no puedo reclamar la multa'], correcta:1 },
  { id:'t8-32', tema:8, n:32, q:'Las infracciones del tránsito incluidas en el primer grupo o "muy peligrosas" -¿Qué cuantía tienen?', opciones:['20 pesos','60 pesos.','40 pesos'], correcta:1 },
  { id:'t8-33', tema:8, n:33, q:'Las infracciones del tránsito incluidas en el segundo grupo o "peligrosas" -¿Qué cuantía tienen?', opciones:['40 pesos.','30 pesos','20 pesos'], correcta:0 },
  { id:'t8-34', tema:8, n:34, q:'Las infracciones del tránsito incluidas en el tercer grupo o "menos peligrosas" -¿Qué cuantía tienen?', opciones:['10 pesos','15 pesos','20 pesos.'], correcta:2 },
  { id:'t8-35', tema:8, n:35, q:'Usted, como titular de licencia de conducción, debe conocer su derecho a establecer la reclamación correspondiente ante su inconformidad por una multa impuesta por infracción de las regulaciones del tránsito, y para ello debe tener presente interponer la reclamación:', opciones:['En el plazo de veinte días naturales siguientes, a la notificación de la infracción','Dentro del término de diez días hábiles, a partir de su notificación.','En el término de 72 horas, a partir de su notificación'], correcta:1 },
  { id:'t8-36', tema:8, n:36, q:'Si usted realiza la reclamación de una multa de tránsito dentro de los 10 días hábiles a partir de su notificación, -¿Esa acción le exime del pago del importe de la misma dentro de los plazos previstos?', opciones:['Sí, en todos los casos','No.','Sí, a veces'], correcta:1 },
  { id:'t8-37', tema:8, n:37, q:'Si usted realiza la reclamación de una multa de tránsito dentro de los 10 días hábiles a partir de su notificación, efectúa su pago a los 20 días y luego la reclamación es declarada con lugar, -¿Qué sucede?', opciones:['Le devuelven el importe pagado y los puntos permanecen en su expediente','No pasa nada','Le devuelven el importe pagado y le quitan los puntos.'], correcta:2 },
  { id:'t8-38', tema:8, n:38, q:'¿Prescriben las infracciones del tránsito al transcurrir un año contado a partir de la notificación?', opciones:['Sí, en todos los casos','No','Sí, generalmente, excepto cuando se haya requerido al infractor para que pague.'], correcta:2 },
  { id:'t8-39', tema:8, n:39, q:'¿Cuándo un titular de una licencia de conducción puede ser sometido a nuevos exámenes médico, teórico y práctico?', opciones:['Al llegar a 60 años de edad','Al existir motivos para ello, fundados en el expediente del conductor o que obren en otros informes o antecedentes.','Al sorprenderse conduciendo en estado de embriaguez'], correcta:1 },
  { id:'t8-40', tema:8, n:40, q:'Para conducir un ciclomotor -¿Qué categoría de licencia se necesita como mínimo?', opciones:['Categoría "A"','Categoría "A-1".','Categoría "B"'], correcta:1 },
  { id:'t8-41', tema:8, n:41, q:'Para conducir una motocicleta -¿Qué categoría de licencia se necesita?', opciones:['Categoría "C"','Categoría "A".','Categoría "B"'], correcta:1 },
  { id:'t8-42', tema:8, n:42, q:'Para conducir un camión -¿Qué categoría de licencia se necesita?', opciones:['Categoría "C".','Categoría "D"','Categoría "B"'], correcta:0 },
  { id:'t8-43', tema:8, n:43, q:'Para conducir un ómnibus -¿Qué categoría de licencia se necesita?', opciones:['Categoría "C"','Categoría "D".','Categoría "E"'], correcta:1 },
  { id:'t9-01', tema:9, n:1, q:'Cuando se prohíbe adelantar a otro vehículo', opciones:['En vías de doble sentido de circulación a 100 metros de un paso a nivel','En los pasos para peatones, señalizados con marcas de tipo cebra','En los cambios de rasante en vías de dos o más sendas en un mismo sentido de circulación'], correcta:1 },
  { id:'t9-02', tema:9, n:2, q:'Además de las luces de niebla, se pueden usar otras luces cuando hay niebla densa o lluvia intensa', opciones:['Si, las de cruce o cortas','Si, las largas o de carretera','No'], correcta:0 },
  { id:'t9-03', tema:9, n:3, q:'En un túnel suficientemente iluminado, es necesario alguna luz', opciones:['Si, las cortas o de posición','No, ya que hay iluminación suficiente','Si, las de parada de emergencia'], correcta:0 },
  { id:'t9-04', tema:9, n:4, q:'Transitando en zona rural de noche, si le piden cambio de luces, a que distancia deberá realizarlo para no deslumbrar al conductor que viene de frente:', opciones:['150 metros','100 metros','50 metros'], correcta:0 },
  { id:'t9-05', tema:9, n:5, q:'Donde un conductor puede realizar la maniobra de madia vuelta o giro en forma de U', opciones:['A menos de 150 metros anteriores a la entrada o posteriores a la salida de una curva de visibilidad reducida o cambio de rasante que no permita ver la conducción de la vía','En intersecciones semaforizadas sin señales verticales, cuando el semáforo esta proyectando la luz autorizando el giro a la izquierda','A 100 metros de un intercambio'], correcta:1 },
  { id:'t9-06', tema:9, n:6, q:'Las luces de cruce o cortas deben alumbrar la vía con eficacia hasta una distancia por delante del vehículo de...', opciones:['40 metros.','50 metros','30 metros'], correcta:0 },
  { id:'t9-07', tema:9, n:7, q:'Las luces de carretera o largas deben alumbrar con eficacia la vía una distancia mínima de....', opciones:['2150 metros','90 metros','100 metros.'], correcta:2 },
  { id:'t9-08', tema:9, n:8, q:'¿Cuántas luces de posición deben tener encendidas los vehículos que circulen en las horas comprendidas del anochecer al amanecer?', opciones:['Dos delante','Dos delante y dos detrás.','Dos detrás'], correcta:1 },
  { id:'t9-09', tema:9, n:9, q:'¿Qué color deben tener las luces de posición traseras en los vehículos?', opciones:['Rojo.','Blanco','Amarillo selectivo'], correcta:0 },
  { id:'t9-10', tema:9, n:10, q:'¿Es obligatoria la luz que ilumina la chapa trasera al circular de noche?', opciones:['Sólo en los autos ligeros','No, pero es aconsejable','Sí.'], correcta:2 },
  { id:'t9-11', tema:9, n:11, q:'La intensidad de la luz roja de frenado es superior a la de la luz de....', opciones:['Cualquier otro sistema de luces','Posición trasera.','Marcha atrás'], correcta:1 },
  { id:'t9-12', tema:9, n:12, q:'En un túnel suficientemente iluminado, -¿es necesario encender alguna luz?', opciones:['Sí, las luces cortas o las de posición.','No, ya que hay iluminación suficiente','Sí, las de parada de emergencia'], correcta:0 },
  { id:'t9-13', tema:9, n:13, q:'En zona urbana, -¿se pueden usar las luces largas o de carretera?', opciones:['Sí, siempre que haya eficiente alumbrado público','No, excepto, cuando es deficiente el alumbrado público.','No, nunca'], correcta:1 },
  { id:'t9-14', tema:9, n:14, q:'Además de las luces de niebla, -¿se pueden usar otras luces cuando hay niebla densa o lluvia intensa?', opciones:['Sí, las luces largas o de carretera','Sí, las de cruce o cortas.','No'], correcta:1 },
  { id:'t9-15', tema:9, n:15, q:'En la zona rural de noche, cuando no se le pide el cambio de luces, -¿a qué distancia aproximada lo debe realizar para no deslumbrar al que viene de frente?', opciones:['150 metros.','100 metros','50 metros'], correcta:0 },
  { id:'t9-16', tema:9, n:16, q:'En la zona rural, en las horas comprendidas del anochecer al amanecer, y cuando circula detrás de otro vehículo, -¿a qué distancia las luces de carretera o largas deben ser sustituidas por las de cruce o cortas para no deslumbrar al que va delante por el espejo retrovisor?', opciones:['A 60 metros','A menos 50 metros.','A 100 metros'], correcta:1 },
  { id:'t9-17', tema:9, n:17, q:'El conductor de cualquier vehículo de motor, cuando circule por la vía, en las horas comprendidas del anochecer al amanecer, en caso de deslumbramiento, está obligado a:', opciones:['Reducir la velocidad lo necesario, incluso hasta la detención total del vehículo, para evitar un accidente.','Moderar la velocidad','Solicitar el cambio de luces al conductor que se aproxima en sentido contrario'], correcta:0 },
  { id:'t9-18', tema:9, n:18, q:'El conductor de cualquier vehículo de motor, cuando circule por la vía, en las horas comprendidas del anochecer al amanecer, para adelantar a otro vehículo, está obligado a:', opciones:['Hacer las señales, apagando y encendiendo las luces','Sonar el claxon','Hacer las señales empleando alternativamente el cambio de luces.'], correcta:2 },
  { id:'t9-19', tema:9, n:19, q:'El conductor de cualquier vehículo de motor, cuando circule por la vía, en las horas comprendidas del anochecer al amanecer, en una curva de visibilidad reducida y en la proximidad de un cambio de rasante, está obligado a:', opciones:['Sustituir las luces de carretera o largas por las de cruce o cortas para evitar el deslumbramiento de los vehículos que se aproximen en sentido contrario','Realizar cambios de luces a intervalos regulares hasta rebasar la zona de no visibilidad.','En zona rural, mantener las luces de carretera o largas y accionar el claxon a intervalos, para advertir a otros usuarios de su presencia en la vía'], correcta:1 },
  { id:'t9-20', tema:9, n:20, q:'Circulando en la corriente vehicular, usted requiere adelantar al vehículo que circula delante. Para realizar la maniobra de adelantamiento, usted está obligado a:', opciones:['Comprobar que nadie circula detrás de usted','Comprobar que puede efectuarlo por senda izquierda, sin ocasionar interferencia a los demás conductores de vehículos.','Realizar la maniobra por encima del límite máximo de velocidad para hacerlo rápido'], correcta:1 },
  { id:'t9-21', tema:9, n:21, q:'¿Está prohibido adelantar un camión pipa que no permite la visibilidad de la parte delantera de la vía destinada al sentido contrario?', opciones:['No, porque me sirve de protección','Sí.','No, si se circula lentamente'], correcta:1 },
  { id:'t9-22', tema:9, n:22, q:'Transitando por una vía de dos carriles y dos sentido de dirección, usted adelantará a la moto que marcha delante:', opciones:['Por la propia senda derecha','Por la derecha, usando el paseo','Por la senda izquierda.'], correcta:2 },
  { id:'t9-23', tema:9, n:23, q:'Todo conductor para realizar un giro a la derecha deberá hacerlo:', opciones:['Desde el carril de la extrema derecha, siempre que las condiciones físicas lo permitan.','Desde la senda de la extrema izquierda','Desde el carril del centro'], correcta:0 },
  { id:'t9-24', tema:9, n:24, q:'Todo conductor para realizar un giro a la izquierda deberá hacerlo:', opciones:['Desde cualquier carril de la calzada por donde circula','Desde el carril de la extrema izquierda de la calzada, en el sentido por donde circula.','Desde el carril del centro'], correcta:1 },
  { id:'t9-25', tema:9, n:25, q:'¿Dónde el conductor de cualquier vehículo puede efectuar la maniobra de media vuelta o giro en forma de "U"?', opciones:['Al aproximarse a un puente','Intersecciones semaforizadas, donde se autoriza la maniobra por la señal correspondiente, durante la proyección de la luz del semáforo autorizando el giro a la izquierda.','A 200 metros anteriores a la entrada o posteriores a la salida de una curva'], correcta:1 },
  { id:'t9-26', tema:9, n:26, q:'¿Dónde el conductor de cualquier vehículo puede efectuar la maniobra de media vuelta o giro en forma de "U"?', opciones:['A menos de 150 metros anteriores a la entrada o posteriores a la salida de una curva de visibilidad reducida o cambio de rasante que no permitan ver la continuación de la vía','En intersecciones semaforizadas, sin señales verticales, cuando el semáforo proyecta la luz autorizando el giro a la izquierda.','A 100 metros de un intercambio'], correcta:1 },
  { id:'t9-27', tema:9, n:27, q:'¿Dónde el conductor de cualquier vehículo puede efectuar la maniobra de media vuelta o giro en forma de "U"?', opciones:['En pasos a nivel, puentes, túneles o intercambio','A 140 metros de una curva de visibilidad reducida','En cualquier lugar en que para efectuar la maniobra no se vea obligado a retroceder.'], correcta:2 },
  { id:'t9-28', tema:9, n:28, q:'Los conductores de motocicletas y ciclomotores deben usar el casco protector debidamente abrochado:', opciones:['Solamente en vías urbanas','Solamente en zona rural','En todas las vías.'], correcta:2 },
  { id:'t9-29', tema:9, n:29, q:'En una motocicleta sin sidecar, -¿Cuántos pasajeros se pueden transportar?', opciones:['Uno delante de él','Uno detrás de él.','Dos detrás de él'], correcta:1 },
  { id:'t9-30', tema:9, n:30, q:'En una motocicleta sin sidecar, -¿Puede transportar a su hijo de 3 años?', opciones:['No, nunca.','Sí, siempre','Sí, a veces, si es para el círculo infantil'], correcta:0 },
  { id:'t9-31', tema:9, n:31, q:'En una motocicleta con sidecar, -¿Puede trasportar a su hijo de 5 años?', opciones:['No, nunca','Sí, de cualquier modo','Sí, a veces, cuando este acompañado por un mayor de 14 años.'], correcta:2 },
  { id:'t9-32', tema:9, n:32, q:'En una motocicleta, -¿Puede transportar bultos o carga?', opciones:['No, nunca, está prohibido ya que afecta la maniobrabilidad','Sí, de cualquier modo','Sí, a veces, en dispositivos adecuados y sin sobresalir más de 50 centímetros.'], correcta:2 },
  { id:'t10-01', tema:10, n:1, q:'Cual es la distancia que debe existir entre dos vehículos en marcha:', opciones:['5 metros por cada 15km/h','2 metros por cada 10 km/h','6 metros por cada 20 km/h'], correcta:0 },
  { id:'t10-02', tema:10, n:2, q:'Está prohibida la circulación por la vía utilizando patines, carriolas o artefactos similares:', opciones:['Si, en todos los casos','No, nunca','Si, excepto en vías cerradas a tal efecto o zona de recreación'], correcta:2 },
  { id:'t10-03', tema:10, n:3, q:'¿Cuándo el conductor de cualquier vehículo está obligado a mantener una posición de frente ante el volante?', opciones:['Siempre.','A veces','Nunca'], correcta:0 },
  { id:'t10-04', tema:10, n:4, q:'¿Cuándo un conductor de cualquier vehículo debe evitar llevar personas encimadas que le impidan la adecuada seguridad en la conducción?', opciones:['A veces','Nunca','Siempre.'], correcta:2 },
  { id:'t10-05', tema:10, n:5, q:'¿Cuándo el conductor de cualquier vehículo puede conducir con una sola mano?', opciones:['Para hacer las señales establecidas para indicar alguna maniobra, efectuar cambios de velocidades y aplicar el freno de seguridad.','Para descansar el brazo','Siempre'], correcta:0 },
  { id:'t10-06', tema:10, n:6, q:'¿Cuándo el conductor cualquier vehículo está obligado a mantener 5 metros de distancia por cada 15 kilómetros por hora de velocidad, entre vehículos que circulen uno detrás de otro?', opciones:['Nunca','A veces','Siempre.'], correcta:2 },
  { id:'t10-07', tema:10, n:7, q:'La distancia mínima de seguridad que debe usted guardar entre el vehículo que conduce y el que le antecede, cuando se desplaza a una velocidad de 60 kilómetros por hora por una vía en zona rural debe ser:', opciones:['15 metros','30 metros','20 metros.'], correcta:2 },
  { id:'t10-08', tema:10, n:8, q:'¿En qué tipo de vehículo el conductor no puede entablar conversación con otra persona mientras el vehículo está en marcha?', opciones:['Vehículo de transporte público de pasajeros.','Camiones','Rastras'], correcta:0 },
  { id:'t10-09', tema:10, n:9, q:'¿Cuándo el conductor de cualquier vehículo puede conducir con menores de 12 años de edad en el asiento delantero?', opciones:['A veces','Nunca.','Siempre'], correcta:1 },
  { id:'t10-10', tema:10, n:10, q:'¿Cuándo el conductor de cualquier vehículo puede transportar a menores de 2 años de edad?', opciones:['Sin acompañamiento de personas mayores','Con aditamentos especiales.','Nunca'], correcta:1 },
  { id:'t10-11', tema:10, n:11, q:'¿Cuándo el conductor de cualquier vehículo puede utilizar teléfonos u otros medios de comunicación mientras el vehículo está en marcha?', opciones:['Nunca','Siempre','En los casos que se empleen aditamentos que permitan utilizarlos sin emplear las manos.'], correcta:2 },
  { id:'t10-12', tema:10, n:12, q:'¿Cuándo el conductor de cualquier vehículo puede usar equipos de audio?', opciones:['A un volumen que no moleste o impida la debida concentración en la conducción del vehículo.','Nunca','Siempre'], correcta:0 },
  { id:'t10-13', tema:10, n:13, q:'¿Queda prohibida la circulación de un vehículo de motor cuando el freno de servicio no acciona uniformemente en todas las ruedas?', opciones:['Sí.','No','A veces'], correcta:0 },
  { id:'t10-14', tema:10, n:14, q:'¿Queda prohibida la circulación de un vehículo de motor cuando existe salidero de aire o de líquido del sistema hidráulico?', opciones:['A veces','No','Sí.'], correcta:2 },
  { id:'t10-15', tema:10, n:15, q:'¿Queda prohibida la circulación de un vehículo de motor cuando no trabaja el manómetro del sistema de aire?', opciones:['A veces','Sí.','No'], correcta:1 },
  { id:'t10-16', tema:10, n:16, q:'¿Queda prohibida la circulación de un vehículo de motor cuando el compresor no produce la presión necesaria para el sistema de aire?', opciones:['Sí.','No','A veces'], correcta:0 },
  { id:'t10-17', tema:10, n:17, q:'¿Queda prohibida la circulación de los remolques y semirremolques de más de 1500 kilogramos cuando no funcionan o no tienen sistema de frenos automáticos?', opciones:['A veces, en el tiro de caña','No','Sí.'], correcta:2 },
  { id:'t10-18', tema:10, n:18, q:'¿Queda prohibida la circulación de los remolques de hasta 1500 kilogramos cuando no disponen de freno, cadena o cable, que en caso de quedar libres, los frenen o sujeten?', opciones:['A veces, cuando los remolca un jeep','Sí.','No'], correcta:1 },
  { id:'t10-19', tema:10, n:19, q:'¿Queda prohibida la circulación de un vehículo de motor cuando el freno de mano no detenga al vehículo con seguridad?', opciones:['Sí.','No','A veces, cuando está cargado'], correcta:0 },
  { id:'t10-20', tema:10, n:20, q:'¿Queda prohibida la circulación de un vehículo de motor cuando la holgura o juego del timón es de más de 25 grados?', opciones:['A veces','No','Sí.'], correcta:2 },
  { id:'t10-21', tema:10, n:21, q:'¿Queda prohibida la circulación de un vehículo de motor cuando el sistema de dirección está desajustado?', opciones:['No','Sí.','A veces'], correcta:1 },
  { id:'t10-22', tema:10, n:22, q:'¿Queda prohibida la circulación de un vehículo de motor cuando existe rigidez en el timón?', opciones:['Sí.','No','A veces'], correcta:0 },
  { id:'t10-23', tema:10, n:23, q:'¿Queda prohibida la circulación de un vehículo de motor cuando el sistema hidráulico de dirección tiene desperfectos?', opciones:['A veces','No','Sí.'], correcta:2 },
  { id:'t10-24', tema:10, n:24, q:'¿Queda prohibida la circulación de un vehículo de motor cuando existen roturas en las cuerdas de los neumáticos?', opciones:['A veces','No','Sí.'], correcta:2 },
  { id:'t10-25', tema:10, n:25, q:'¿Queda prohibida la circulación de un vehículo de motor cuando la superficie de los neumáticos presenta el desgaste máximo?', opciones:['No','Sí.','A veces'], correcta:1 },
  { id:'t10-26', tema:10, n:26, q:'¿Queda prohibida la circulación de un vehículo de motor cuando la medida de los neumáticos no se corresponde con el peso del vehículo?', opciones:['Sí.','A veces, para ahorrar combustible','No'], correcta:0 },
  { id:'t10-27', tema:10, n:27, q:'¿Queda prohibida la circulación de un vehículo de motor cuando no presentan las ruedas delanteras los ajustes normados por los fabricantes?', opciones:['Sí.','No','A veces'], correcta:0 },
  { id:'t10-28', tema:10, n:28, q:'¿Queda prohibida la circulación de un vehículo de motor cuando existen salideros de combustible?', opciones:['Sí.','No','A veces, cuando hay mucho tránsito'], correcta:0 },
  { id:'t10-29', tema:10, n:29, q:'¿Queda prohibida la circulación de un vehículo de motor cuando se desconectan las velocidades de la caja?', opciones:['A veces','No','Sí.'], correcta:2 },
  { id:'t10-30', tema:10, n:30, q:'¿Queda prohibida la circulación de un vehículo de motor cuando vibra la trasmisión?', opciones:['Sí, siempre.','No, nunca','Sí, a veces, cuando se va despacio'], correcta:0 },
  { id:'t10-31', tema:10, n:31, q:'¿Queda prohibida la circulación de un vehículo de motor cuando los gases de escape contienen una cantidad de gas carbónico superior a la norma?', opciones:['No, nunca','Sí, a veces, en los vehículos pesados y en vías montañosas','Sí, siempre.'], correcta:2 },
  { id:'t10-32', tema:10, n:32, q:'¿Queda prohibida la circulación de un vehículo de motor cuando le falta el tubo de escape o el silenciador?', opciones:['No, nunca','Sí, siempre.','Sí, a veces, cuando es una moto'], correcta:1 },
  { id:'t10-33', tema:10, n:33, q:'¿Cuántos espejos retrovisores deben tener los vehículos?', opciones:['Sólo dos','Depende del tipo de vehículo.','Uno solamente'], correcta:1 },
  { id:'t10-34', tema:10, n:34, q:'Los vehículos que están obligados a estar provistos de un cinturón de seguridad -¿Cuándo deben usarlo?', opciones:['Nunca','Siempre.','A veces, solo en zona rural'], correcta:1 },
  { id:'t10-35', tema:10, n:35, q:'¿Qué tipos de vehículos están obligados a estar provistos de parabrisas?', opciones:['Todos los vehículos de motor','Todos los vehículos','Todos los automóviles, excepto las motocicletas.'], correcta:2 },
  { id:'t10-36', tema:10, n:36, q:'¿Está permitido llevar fijado en los parabrisas o cristales, cortinas, anuncios, calcomanías u otros similares que limiten la visibilidad del conductor?', opciones:['Sí, en cualquier caso','Sí, si se tiene espejo retrovisor','No, nunca, por estar prohibido.'], correcta:2 },
  { id:'t10-37', tema:10, n:37, q:'¿Cuántos limpiaparabrisas, como mínimo, deben tener los automóviles?', opciones:['Dos','Ninguno, no es obligatorio ya que no siempre está lloviendo','Uno, frente al conductor.'], correcta:2 },
  { id:'t10-38', tema:10, n:38, q:'¿Está permitido a los automóviles circular sin chapas de identificación?', opciones:['No, nunca.','Sí, en cualquier caso','A veces, cuando está de prueba por el taller'], correcta:0 },
  { id:'t10-39', tema:10, n:39, q:'¿Qué tipos de vehículos deben estar provistos de extintor de incendio?', opciones:['Todos los tipos.','Solo los vehículos de transporte de carga','Ómnibus y vehículos de transporte de carga.'], correcta:0 },
  { id:'t10-40', tema:10, n:40, q:'¿Cuándo un poseedor legal debe someter su vehículo a inspección o revisión técnica?', opciones:['Nunca, ya que no es obligatorio','Cuando se le indique por las autoridades ya que es obligatorio.','Cuando desee ya que es opcional'], correcta:1 },
  { id:'t10-41', tema:10, n:41, q:'La inspección técnica de un vehículo se ejecuta por:', opciones:['Ministerio de la Industria Sideromecánica para medios muy modernos','Ministerio del Transporte en todos los vehículos nuevos','Ministerio del Interior y además, en los vehículos de carga y ómnibus, el Ministerio del Transporte.'], correcta:2 },
  { id:'t10-42', tema:10, n:42, q:'Si un vehículo inspeccionado técnicamente no reúne los requisitos establecidos el Ministerio del Interior retirará:', opciones:['Licencia de circulación y chapas.','Licencia de conducción','Licencia de circulación y licencia de conducción'], correcta:0 },
  { id:'t10-43', tema:10, n:43, q:'¿Pueden circular los vehículos sin que estén provistos del certificado de revisión técnica?', opciones:['Sí, en cualquier caso.','No, nunca','Sí, a veces, ya que es opcional'], correcta:0 },
  { id:'t10-44', tema:10, n:44, q:'¿Cuándo los poseedores de los vehículos están obligados a comunicar al Registro de Vehículos los traspasos de propiedad, cambios de carrocerías y las conversiones?', opciones:['Siempre, ya que es obligatorio.','Nunca','A veces, ya que es opcional'], correcta:0 },
  { id:'t10-45', tema:10, n:45, q:'¿Cuándo no está prohibido fumar en los vehículos de motor?', opciones:['Se conduce un vehículo de carga.','Se conduce un vehículo de transporte público urbano de pasajeros','Se conduce un vehículo de transporte de materiales inflamables o explosivos'], correcta:0 },
  { id:'t10-46', tema:10, n:46, q:'¿Está prohibido fumar a los pasajeros de los vehículos de motor?', opciones:['Sí, a veces, cuando se circula en vehículo de transporte público urbano de pasajeros o de transporte de materiales inflamables o explosivos.','Sí, en cualquier caso','No, nunca'], correcta:0 },
  { id:'t10-47', tema:10, n:47, q:'¿Puede un conductor de un vehículo en marcha realizar una detención de manera rápida o violenta?', opciones:['Sí, siempre, ya que está permitido totalmente','No, nunca','Sí, a veces, en casos de fuerza mayor y haciendo la señal adecuada.'], correcta:2 },
  { id:'t10-48', tema:10, n:48, q:'¿Está permitido que usted conduciendo un automóvil remolque a una bicicleta?', opciones:['Sí, siempre, ya que está permitido totalmente','No, nunca, ya que está prohibido.','Si, a veces, con el permiso del Ministerio del Interior'], correcta:1 },
  { id:'t10-49', tema:10, n:49, q:'¿Está prohibida la circulación por la vía utilizando patines, carriolas o artefactos similares?', opciones:['Sí, en todos los casos y modos','No, nunca','Sí, excepto en vías cerradas a tal efecto o zona de recreación.'], correcta:2 },
  { id:'t6-01', tema:6, n:1, q:'La señal de fondo azul y flecha de color blanco:', opciones:['Vía en sentido único','Sentido de circulación','Placa completaría'], correcta:1, senales:['f-sentido-circulacion'], ref:'Art. 170.2 — señales de información (Grupo F)' },
  { id:'t6-02', tema:6, n:2, q:'Que indica esta señal de peligro', opciones:['Indica proximidad de dos o más curvas, la primera a la derecha','Indica que los vehículos deben pasar obligatoriamente por el lado del obstáculo que señala la flecha','Indica la proximidad de rampas peligrosas, la primera a la derecha'], correcta:0, senales:['a-doble-curva-derecha'], ref:'Art. 160.13 — señales de peligro (Grupo A)' },
  { id:'t6-03', tema:6, n:3, q:'Usted como conductor de un vehículo, al observar esta señal, que conducta deberá adoptar', opciones:['Detener la marcha ante la presencia de la línea de Pare','Disminuir velocidad y parar si fuera necesario','Moderar velocidad y parar cuando las condiciones de velocidad así lo aconsejen'], correcta:0, senales:['b-pare'], ref:'Art. 78.1 y Art. 162.1 — señal de Pare' },
  { id:'t6-04', tema:6, n:4, q:'¿Cuántas de estas señales advierten la existencia de un peligro?', opciones:['Una.','Dos.','Tres.'], correcta:1, senales:['a-paso-nivel-con-proteccion','a-bajada-peligrosa'], ref:'Art. 159 y 160 — Grupo A: señales de peligro o precaución' },
  { id:'t6-05', tema:6, n:5, q:'¿Se debe ceder el paso a los vehículos que se incorporen a la vía en que está colocada esta señal?', opciones:['A veces.','Sí.','No.'], correcta:2, senales:['b-via-con-prioridad'], ref:'Art. 162.5 — vía con prioridad' },
  { id:'t6-06', tema:6, n:6, q:'¿Qué indica esta señal de peligro:', opciones:['Indica el cruce de una carretera o camino con otra de igual categoría.','Un entronque lateral derecho.','Un entronque lateral izquierdo.'], correcta:0, senales:['a-cruce'], ref:'Art. 160.4 — cruce' },
  { id:'t6-07', tema:6, n:7, q:'Esta señal indica...:', opciones:['Que se permite el giro en "U".','La proximidad de un lugar donde está establecido un sentido giratorio para la circulación.','Una curva peligrosa a la izquierda.'], correcta:1, senales:['a-circulacion-giratoria'], ref:'Art. 160.6 — circulación giratoria' },
  { id:'t6-08', tema:6, n:8, q:'¿Qué significa esta señal?', opciones:['La proximidad de un paso a nivel con barrera.','La proximidad de un perfil irregular o badén.','La proximidad de una bajada peligrosa.'], correcta:0, senales:['a-paso-nivel-con-proteccion'], ref:'Art. 160.7 — paso a nivel con sistema de protección' },
  { id:'t6-09', tema:6, n:9, q:'¿Qué significa esta señal?', opciones:['La salida de un muelle o orilla.','Desprendimiento de rocas.','La proximidad de un paso a nivel sin barrera.'], correcta:2, senales:['a-paso-nivel-sin-proteccion'], ref:'Art. 160.8 — paso a nivel sin sistema de protección' },
  { id:'t6-10', tema:6, n:10, q:'Estas señales están relacionadas:', opciones:['Con las pendientes ascendentes o descendentes.','Con los cambios bruscos de rasante o los badenes.','Con los puertos de montaña y los valles respecto a su inclinación.'], correcta:1, senales:['a-perfil-irregular'], ref:'Art. 160.10 — perfil irregular o badén' },
  { id:'t6-11', tema:6, n:11, q:'Usted, como conductor, debe conocer que la señal que le presentamos:', opciones:['Indica la proximidad de una intersección donde se prohíbe girar a la derecha.','Indica la proximidad a una curva hacia el lado derecho del sentido de la circulación.','Indica a los vehículos el sentido que deben seguir obligatoriamente en el punto donde está situada la señal.'], correcta:1, senales:['a-curva-derecha'], ref:'Art. 160.11 — curva peligrosa a la derecha' },
  { id:'t6-12', tema:6, n:12, q:'Usted, como conductor, debe conocer que la señal que le presentamos:', opciones:['Indica la proximidad de dos o más curvas, la primera a la derecha.','Indica a los vehículos que deben pasar obligatoriamente por el lado del obstáculo que señala la flecha.','Indica la proximidad de rampas peligrosas, la primera a la derecha.'], correcta:0, senales:['a-doble-curva-derecha'], ref:'Art. 160.13 — doble curva peligrosa a la derecha' },
  { id:'t6-13', tema:6, n:13, q:'Según esta señal, próximamente se encuentra un tramo de vía:', opciones:['Con tierra o arena donde las ruedas patinan.','En obras.','Con presencia de personas en labores agrícolas.'], correcta:1, senales:['a-obras'], ref:'Art. 160.23 — obras' },
  { id:'t6-14', tema:6, n:14, q:'¿Qué significa esta señal?', opciones:['Prohibición de cruce de peatones.','Indica la proximidad de un pavimento resbaladizo.','Lugar frecuentado por ciclistas.'], correcta:1, senales:['a-pavimento-resbaladizo'], ref:'Art. 160.24 — pavimento resbaladizo' },
  { id:'t6-15', tema:6, n:15, q:'¿Qué significa esta señal?', opciones:['Detener la marcha.','Moderar la velocidad.','Continuar a la velocidad máxima de la vía.'], correcta:0, senales:['b-pare'], ref:'Art. 78.1 — detener la marcha ante la señal de Pare' },
  { id:'t6-16', tema:6, n:16, q:'Usted, como conductor, ¿qué conducta deberá seguir al observar esta señal?', opciones:['No exceder los 50 kilómetros por hora de velocidad, en zona urbana o rural','En zona urbana o rural, disminuir la velocidad, establecida para la vía, en correspondencia con sus condiciones de visibilidad.','En zona urbana, no exceder los 40 kilómetros por hora de velocidad y los 60 kilómetros por hora de velocidad, en zona rural.'], correcta:2, senales:['a-ninos'], ref:'Art. 127.5 y 135 — 40 km/h en zona urbana y 60 km/h en zona rural' },
  { id:'t6-17', tema:6, n:17, q:'Usted, como conductor, debe conocer que la señal que le presentamos:', opciones:['Indica la proximidad de una zona por la que cruzan frecuentemente animales domésticos o grupo de animales.','Indica la prohibición de cruce y circulación de ganado por el punto de la vía donde está situada la señal.','Indica el punto de la vía por donde se autoriza el cruce la circulación del ganado.'], correcta:0, senales:['a-animal-domestico'], ref:'Art. 160.27 — cruce de animal doméstico' },
  { id:'t6-18', tema:6, n:18, q:'A partir de esta señal, usted sabe que existe peligro por la proximidad de una zona de la calzada donde la circulación se realiza:', opciones:['Con prioridad de los vehículos que se aproximan en sentido contrario.','De forma paralela.','En los dos sentidos.'], correcta:2, senales:['a-doble-sentido'], ref:'Art. 160.29 — doble sentido de circulación' },
  { id:'t6-19', tema:6, n:19, q:'Usted, como conductor, debe conocer que la señal que le presentamos:', opciones:['Prohíbe la circulación a los ciclos y otros vehículos de tracción humana o animal.','Indica la obligación de los ciclistas a utilizar la vía o la parte de ella donde está situada la señal y que los demás usuarios de la vía no tienen derecho a usarla.','Indica la proximidad de un paso frecuentado por ciclistas en la vía o que la atraviesan.'], correcta:2, senales:['a-salida-ciclistas'], ref:'Art. 160.32 — salida de ciclistas' },
  { id:'t6-20', tema:6, n:20, q:'Usted, como conductor, debe conocer que la señal que le presentamos:', opciones:['Indica la proximidad de dos o más curvas, la primera a la izquierda.','Indica la proximidad de un desvío en la circulación motivado por reparaciones en la vía.','Indica la existencia de un terraplén.'], correcta:1, senales:['a-desvio'], ref:'Art. 160.35 — desvío' },
  { id:'t6-21', tema:6, n:21, q:'¿Cuántas de estas señales establecen algún régimen de prioridad?', opciones:['Una.','Dos.','Tres.'], correcta:1, senales:['b-ceda-el-paso','b-prioridad-sentido-contrario','a-otros-peligros'], ref:'Art. 162 — señales de prioridad (Grupo B)' },
  { id:'t6-22', tema:6, n:22, q:'Usted, como conductor de cualquier vehículo, ¿qué conducta deberá seguir al observar esta señal?', opciones:['Detener la marcha, cualesquiera que sean las circunstancias de visibilidad dándole prioridad a los vehículos que circulan por la vía transversal.','Disminuir la velocidad y parar si fuera necesario, a fin de permitir el paso a todos los vehículos que se aproximen por la vía transversal','Moderar la velocidad y parar cuando las condiciones de visibilidad así lo aconsejen, continuando la marcha cuando no se aproxime ningún vehículo por la vía transversal'], correcta:0, senales:['b-pare'], ref:'Art. 78.1 y Art. 162.1 — señal de Pare' },
  { id:'t6-23', tema:6, n:23, q:'Usted, como conductor de cualquier vehículo, ¿qué conducta deberá seguir al observar esta señal?', opciones:['Detener la marcha, cualesquiera que sean las circunstancias de visibilidad, dándole prioridad a los vehículos que se aproximan por la vía transversal.','Ceder el paso o detenerse si es necesario, dándole prioridad a los vehículos que por la vía transversal se aproximan por el lado derecho.','Disminuir la velocidad y parar si fuera necesario, a fin de permitirle el paso a todos los vehículos que se aproximen por la vía transversal.'], correcta:2, senales:['b-ceda-el-paso'], ref:'Art. 78.2 y Art. 162.2 — señal de Ceda el Paso' },
  { id:'t6-24', tema:6, n:24, q:'Esta señal indica:', opciones:['Todo vehículo está obligado a detenerse en la vertical de la señal','La vía tiene preferencia en los cruces respecto a todas las demás vías que la atraviesan.','Todo vehículo está obligado a disminuir la velocidad'], correcta:1, senales:['b-via-con-prioridad'], ref:'Art. 162.5 — vía con prioridad' },
  { id:'t6-25', tema:6, n:25, q:'Esta señal le indica que:', opciones:['Todo vehículo está obligado a disminuir la velocidad','Todo vehículo está obligado a detenerse en la vertical de la señal','La preferencia en la vía por la cual se circula ha concluido.'], correcta:2, senales:['b-fin-via-con-prioridad'], ref:'Art. 162.6 — fin de la vía con prioridad' },
  { id:'t6-26', tema:6, n:26, q:'Como conductor de cualquier vehículo, usted debe tener presente que esta señal le indica:', opciones:['A los conductores de vehículos que pueden realizar en las intersecciones semaforizadas giros de derecha o seguir recto con extrema precaución, cediéndoles el paso a los conductores y peatones que transitan por la intersección con la luz verde correspondiente.','Que todo vehículo está obligado a disminuir la velocidad y parar si fuera n ecesario, para permitir el paso a todos los vehículos que circulan por la vía preferente.','Que los conductores de vehículos pueden continuar la marcha en las intersecciones de bajo volumen de tránsito ya que tienen prioridad'], correcta:0, senales:['b-ceda-luz-roja'], ref:'Art. 162.7 — ceda el paso con luz roja' },
  { id:'t6-27', tema:6, n:27, q:'¿Cuántas de estas señales son de prohibición?', opciones:['Una.','Dos.','Tres.'], correcta:0, senales:['c-circulacion-prohibida','d-sentido-obligatorio-giro-derecha','d-sentido-obligatorio-giro-izquierda'], ref:'Art. 163 y 164 — señales de prohibición (Grupo C)' },
  { id:'t6-28', tema:6, n:28, q:'¿Cuántas de estas señales son de prohibición?', opciones:['Una.','Dos.','Tres.'], correcta:1, senales:['c-acceso-prohibido','d-via-ciclistas','c-prohibido-ciclos'], ref:'Art. 163 y 164 — señales de prohibición (Grupo C)' },
  { id:'t6-29', tema:6, n:29, q:'¿Cuántas de estas señales son del grupo de fin de prohibición u obligación?', opciones:['Una.','Dos.','Tres.'], correcta:0, senales:['e-fin-velocidad-maxima','c-prohibido-remolque','d-sentido-giratorio'], ref:'Art. 167 y 168 — fin de prohibición u obligación (Grupo E)' },
  { id:'t6-30', tema:6, n:30, q:'¿Cuántas de estas señales indican el punto donde existe un paso de peatones?', opciones:['Una.','Dos.','Tres.'], correcta:0, senales:['f-paso-peatones-cebra','d-via-peatones','a-paso-peatones-cebra'], ref:'Art. 170.28 — paso de peatones (Grupo F)' },
  { id:'t6-31', tema:6, n:31, q:'Usted, como conductor, debe conocer que la señal que le presentamos indica:', opciones:['La prohibición de circular por una vía en los dos sentidos, a todos los vehículos, incluyendo los de tracción animal o humana.','Que la circulación está prohibida a todos los vehículos de motor incluyendo las motocicletas.','La prohibición de circular por la vía a todos los vehículos, inclusive los de tracción animal o humana, en el sentido hacia el cual indica la señal y se permite circular en el sentido opuesto.'], correcta:0, senales:['c-circulacion-prohibida'], ref:'Art. 164.1 — circulación prohibida' },
  { id:'t6-32', tema:6, n:32, q:'Usted, como conductor, debe conocer que la señal de forma circular que le presentamos indica:', opciones:['La prohibición de circular por una vía en los dos sentidos, a todos los vehículos, incluyendo los de tracción animal o humana.','La prohibición de circular por la vía a todos los vehículos, incluso los de tracción animal o humana, en el sentido hacia el cual indica la señal y se permite circular en el sentido opuesto.','Que la circulación es obligatoria a todos los vehículos de motor incluyendo las motocicletas.'], correcta:1, senales:['c-acceso-prohibido'], ref:'Art. 164.2 — acceso prohibido' },
  { id:'t6-33', tema:6, n:33, q:'Usted, como conductor, debe conocer que la señal que le presentamos indica:', opciones:['Que la circulación está prohibida a los vehículos de motor cuyo peso no exceda los 3 500 kilogramos, incluyendo las motocicletas.','Que los automóviles, excepto las motocicletas de dos rueda, que tienen la obligación de circular por la vía señalada.','Circulación prohibida a todos los vehículos de motor, excepto las motocicletas.'], correcta:2, senales:['c-prohibido-motor-excepto-motos'], ref:'Art. 164.3 — circulación prohibida excepto motocicletas' },
  { id:'t6-34', tema:6, n:34, q:'Usted, como conductor de cualquier vehículo, debe conocer que la señal que le presentamos indica:', opciones:['Circulación prohibida a las motocicletas.','A las motocicletas de dos ruedas y a los ciclomotores que tienen la obligación de circular por la vía señalada','Que la circulación está prohibida a todos los vehículos de motor excepto las motocicletas'], correcta:0, senales:['c-prohibido-motocicletas'], ref:'Art. 164.4 — circulación prohibida a las motocicletas' },
]
